42	    /** The grade a person (sheet, person id) has on a date: the one with the latest from-date on
43	     *  or before it, the first one they were given applying from the beginning of time. */
44	    private static final String GRADE_ON = "(SELECT g.grade FROM person_grade g WHERE g.sheet_id = ? AND g.person_id = ?"
45	            + " AND (g.from_date IS NULL OR g.from_date <= CAST(? AS DATE)) ORDER BY g.from_date DESC NULLS LAST LIMIT 1)";
46	
47	    /** The rate a sheet has for a grade on a date (sheet, grade, then the date): the one with the latest
48	     *  from-date on or before it, an undated rate applying from the beginning of time; at most one row, with
49	     *  its pct and to_date. */
50	    private static final String RATE_FOR = "(SELECT r.pct, r.to_date FROM rate r WHERE r.sheet_id = ? AND r.grade = ?"
51	            + " AND (r.from_date IS NULL OR r.from_date <= CAST(? AS DATE)) ORDER BY r.from_date DESC NULLS LAST LIMIT 1)";
52	
53	    /** The rate a sheet's claim takes for a grade on a date (sheet, grade, the date, then the claim's added number):
54	     *  as {@link #RATE_FOR}, among only the rate versions that apply to the claim — those that apply to every claim
55	     *  and the forward-only ones saved before it was added — the newest version of each from-date; at most one row,
56	     *  with its pct and to_date. */
57	    private static final String CLAIM_RATE_FOR = "(SELECT r.pct, r.to_date FROM (SELECT sheet_id, grade, from_date, version,"
58	            + " pct, to_date, after_seq FROM rate UNION ALL SELECT sheet_id, grade, from_date, version, pct, to_date, after_seq"
59	            + " FROM rate_version) r WHERE r.sheet_id = ? AND r.grade = ?"
60	            + " AND (r.from_date IS NULL OR r.from_date <= CAST(? AS DATE)) AND (r.after_seq IS NULL OR r.after_seq < ?)"
61	            + " ORDER BY r.from_date DESC NULLS LAST, r.version DESC LIMIT 1)";
