85	    /** The given claims as the sheet lists them: people in list order (by their position), each person's claims
86	     *  newest first (a reassigned claim counts as its new person's newest); ids the sheet does not have are left out. */
87	    public List<Claim> inListOrder(String sheetId, Collection<Long> ids) {
88	        List<Claim> out = new ArrayList<>();
89	        for (Claim c : list(sheetId)) {
90	            if (ids.contains(c.id())) out.add(c);
91	        }
92	        Map<Long, Integer> place = new java.util.HashMap<>();
93	        for (Long pid : jdbc.queryForList("SELECT id FROM person WHERE sheet_id = ? ORDER BY list_position, id",
94	                Long.class, sheetId)) {
95	            place.put(pid, place.size());
96	        }
97	        out.sort(Comparator.comparingInt((Claim c) -> place.getOrDefault(c.personId(), Integer.MAX_VALUE)));
98	        return out;
99	    }
