143	    /** Record the sheet's today as the claim's pending day (it has just gone to PENDING). */
144	    public void pendingDay(String sheetId, long claimId) {
145	        kept(sheetId, claimId, jdbc.update("UPDATE claim SET pending_day = ? WHERE id = ? AND sheet_id = ?",
146	                java.sql.Date.valueOf(settings.today(sheetId)), claimId, sheetId) > 0);
147	    }
