156	        jdbc.query("SELECT id, pending_day FROM claim WHERE sheet_id = ? AND status = 'PENDING' AND pending_day IS NOT NULL",
157	                rs -> {
158	                    late.put(String.valueOf(rs.getLong("id")),
159	                            rs.getDate("pending_day").toLocalDate().plusDays(sla).isBefore(today));
160	                }, sheetId);
161	        return late;
162	    }
