180	    /** Record the reason a claim was voided with. */
181	    public void voidReason(String sheetId, long claimId, String reason) {
182	        kept(sheetId, claimId, jdbc.update("UPDATE claim SET void_reason = ? WHERE id = ? AND sheet_id = ?", reason, claimId, sheetId) > 0);
