185	    /** Give a settled claim the next number of its sheet's tree within the fiscal year its due-by ({@code date})
186	     *  falls in, FY<yyyy>-<n>: one after the last number given in that fiscal year on any sheet of the tree (the
187	     *  sheet's topmost ancestor and all its descendants). The fiscal year follows the sheet's fiscal start month.
188	     *  The tree's sheet rows stay locked until the transaction commits, so two claims settled at once anywhere in
189	     *  the tree get consecutive numbers. */
190	    public String number(String sheetId, long claimId, LocalDate date) {
191	        List<String> tree = tree(sheetId);
192	        String in = String.join(",", java.util.Collections.nCopies(tree.size(), "?"));
193	        jdbc.update("UPDATE sheet SET claim_number = claim_number WHERE id IN (" + in + ")", tree.toArray());
194	        Integer startMonth = jdbc.queryForObject("SELECT fiscal_start_month FROM sheet WHERE id = ?", Integer.class, sheetId);
195	        int year = date.getMonthValue() >= (startMonth == null ? 1 : startMonth) ? date.getYear() : date.getYear() - 1;
196	        String key = "FY" + year;
197	        List<Object> args = new ArrayList<>(tree);
198	        args.add(key);
199	        Long last = jdbc.queryForObject("SELECT MAX(last_no) FROM claim_sequence WHERE sheet_id IN (" + in + ")"
200	                + " AND seq_key = ?", Long.class, args.toArray());
201	        long next = (last == null ? 0 : last) + 1;
202	        if (jdbc.update("UPDATE claim_sequence SET last_no = ? WHERE sheet_id = ? AND seq_key = ?", next, sheetId, key) == 0) {
203	            jdbc.update("INSERT INTO claim_sequence (sheet_id, seq_key, last_no) VALUES (?, ?, ?)", sheetId, key, next);
204	        }
205	        String number = key + "-" + next;
206	        jdbc.update("UPDATE claim SET claim_no = ? WHERE id = ? AND sheet_id = ?", number, claimId, sheetId);
207	        kept(sheetId, claimId, true);
208	        return number;
209	    }
210	
211	    /** The sheets of the sheet's tree, sorted: its topmost ancestor (following parents) and all that one's
212	     *  descendants, the sheet itself always among them. */
213	    private List<String> tree(String sheetId) {
214	        String root = sheetId;
215	        java.util.Set<String> seen = new java.util.HashSet<>(List.of(sheetId));
216	        for (String at = parentOf(root); at != null && seen.add(at); at = parentOf(at)) root = at;
217	        java.util.Set<String> found = new java.util.TreeSet<>(List.of(root));
218	        java.util.Deque<String> pending = new java.util.ArrayDeque<>(List.of(root));
219	        while (!pending.isEmpty()) {
220	            for (String child : jdbc.queryForList("SELECT id FROM sheet WHERE parent_id = ?", String.class, pending.poll())) {
221	                if (found.add(child)) pending.add(child);
222	            }
223	        }
224	        found.add(sheetId);
225	        return new ArrayList<>(found);
226	    }
227	
228	    private String parentOf(String sheetId) {
229	        List<String> found = jdbc.queryForList("SELECT parent_id FROM sheet WHERE id = ?", String.class, sheetId);
230	        return found.isEmpty() ? null : found.get(0);
231	    }
232	
233	    /** Whether claims settled now are numbered per period: the sheet's period numbering from-date is set
234	     *  and its today is on or after it. */
235	    public boolean numbersPerPeriod(String sheetId) {
236	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ? AND period_numbering_from IS NOT NULL"
237	                + " AND today >= period_numbering_from", Integer.class, sheetId);
238	        return n != null && n > 0;
239	    }
240	
241	    /** Give a settled claim the next number in the sequence of the period its due-by ({@code date}) falls in,
242	     *  <period name>-<n>, or X-<n> when it is in no period. The sheet's row is locked first, so two
243	     *  claims settled at once get consecutive numbers. */
244	    public String numberInPeriod(String sheetId, long claimId, LocalDate date) {
245	        jdbc.update("UPDATE sheet SET claim_number = claim_number WHERE id = ?", sheetId);
246	        List<Object[]> period = periodOn(sheetId, date);
247	        String key = period.isEmpty() ? "X" : "P" + period.get(0)[0];
248	        String prefix = period.isEmpty() ? "X" : (String) period.get(0)[1];
249	        if (jdbc.update("UPDATE claim_sequence SET last_no = last_no + 1 WHERE sheet_id = ? AND seq_key = ?",
250	                sheetId, key) == 0) {
251	            jdbc.update("INSERT INTO claim_sequence (sheet_id, seq_key, last_no) VALUES (?, ?, 1)", sheetId, key);
252	        }
253	        Long next = jdbc.queryForObject("SELECT last_no FROM claim_sequence WHERE sheet_id = ? AND seq_key = ?",
254	                Long.class, sheetId, key);
255	        String number = prefix + "-" + next;
256	        jdbc.update("UPDATE claim SET claim_no = ? WHERE id = ? AND sheet_id = ?", number, claimId, sheetId);
257	        kept(sheetId, claimId, true);
258	        return number;
259	    }
