276	    /** Set a DRAFT, OPEN or PENDING claim's due-by directly; it stays as set from now on. */
277	    public boolean setDueBy(String sheetId, long claimId, LocalDate dueBy) {
278	        return kept(sheetId, claimId, jdbc.update("UPDATE claim SET due_by = ?, due_by_set = TRUE WHERE id = ? AND sheet_id = ?"
279	                + " AND status IN ('DRAFT', 'OPEN', 'PENDING')", Date.valueOf(dueBy), claimId, sheetId) > 0);
