711	    /** Re-fix, after a holiday is added to the sheet, the due-by of each claim not SETTLED or VOID whose due-by is on
712	     *  or after it: the terms-th business day after its date over the sheet's holidays now, for the terms it was fixed
713	     *  with (the business days from the date it was fixed from — its date, unless an edit or re-date moved that — to its
714	     *  due-by over the holidays before, {@code before}). A claim whose
715	     *  due-by moves is kept in the history. */
716	    public void refixDueBy(String sheetId, java.util.Set<String> before, LocalDate holiday) {
717	        java.util.Set<String> now = new java.util.HashSet<>(before);
718	        now.add(holiday.toString());
719	        List<Object[]> open = jdbc.query("SELECT id, claim_date, COALESCE(due_from, claim_date) AS due_from, due_by FROM claim"
720	                + " WHERE sheet_id = ? AND status NOT IN ('SETTLED', 'VOID') AND due_by >= ? AND NOT due_by_set ORDER BY id",
721	                (rs, i) -> new Object[] { rs.getLong("id"), rs.getDate("claim_date").toLocalDate(),
722	                        rs.getDate("due_from").toLocalDate(), rs.getDate("due_by").toLocalDate() }, sheetId, Date.valueOf(holiday));
723	        for (Object[] c : open) {
724	            LocalDate date = (LocalDate) c[1];
725	            LocalDate old = (LocalDate) c[3];
726	            // the terms it was fixed with count from the date it was fixed from, which an edit or re-date may have moved off
727	            LocalDate fixed = SettingsRepository.businessDaysAfter(now, date, businessDaysBetween(before, (LocalDate) c[2], old));
728	            if (fixed.equals(old)) continue;
729	            jdbc.update("UPDATE claim SET due_by = ? WHERE id = ? AND sheet_id = ?", Date.valueOf(fixed), c[0], sheetId);
730	            history.claim(sheetId, (Long) c[0]);
731	        }
732	    }
