782	    private boolean lateEntry(String sheetId, LocalDate date) {
783	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND soft_closed"
784	                + " AND from_date <= ? AND to_date >= ?", Integer.class, sheetId, Date.valueOf(date), Date.valueOf(date));
785	        return n != null && n > 0;
