  6	/** The signed-in user of a request: the name the front end sends in the X-User header. */
  7	public final class CurrentUser {
  8	    public static final String HEADER = "X-User";
  9	
 10	    private CurrentUser() {
 11	    }
 12	
 13	    /** The trimmed name, refused when blank. A step takes the {@link ServerHttpConnection} and
 14	     *  passes it here (header names are matched ignoring case, as browsers send them lower-case). */
 15	    public static String require(ServerHttpConnection connection) throws BadRequestException {
 16	        String name = "";
 17	        for (HttpHeader header : connection.getRequest().getHeaders()) {
 18	            if (HEADER.equalsIgnoreCase(header.getName())) {
 19	                name = header.getValue() == null ? "" : header.getValue().trim();
 20	                break;
 21	            }
 22	        }
 23	        if (name.isEmpty()) {
 24	            throw new BadRequestException("not signed in");
 25	        }
 26	        return name;
 27	    }
 28	}
 29	package net.officefloor.hq.app;
 30	
 31	import java.io.IOException;
 32	import java.io.UncheckedIOException;
 33	import java.nio.charset.StandardCharsets;
 34	import java.nio.file.Files;
 35	import java.nio.file.Path;
 36	import java.nio.file.StandardOpenOption;
 37	import java.util.ArrayList;
 38	import java.util.Collections;
 39	import java.util.List;
 40	import java.util.Locale;
 41	import java.util.Set;
 42	import net.officefloor.hq.app.settings.SettingsRepository;
 43	import org.springframework.beans.factory.ObjectProvider;
 44	import org.springframework.beans.factory.annotation.Value;
 45	import org.springframework.stereotype.Service;
 46	
 47	/**
 48	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 49	 * so tests can assert side-effects by reading that file — the second test-assertion channel
 50	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 51	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 52	 *
 53	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 54	 * SYNC) so a test reads the record immediately.
 55	 */
 56	@Service
 57	public class Audit {
 58	
 59	    /** The lines that only report figures (or tell of a change already recorded): never marked for a delegator. */
 60	    private static final Set<String> REPORTS = Set.of("ROLLUP", "TOTALS", "SNAPSHOT", "ALERT", "NOTIFY");
 61	
 62	    private final Path file;
 63	
 64	    private final ObjectProvider<SettingsRepository> settings;
 65	
 66	    /** The records held back on this thread while a change that may still be refused runs (see {@link #held}). */
 67	    private final ThreadLocal<List<String>> held = new ThreadLocal<>();
 68	
 69	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<SettingsRepository> settings) {
 70	        this.file = Path.of(path);
 71	        this.settings = settings;
 72	    }
 73	
 74	    /** Append one audit record. Tests assert the exact line(s) in the file. A change made by a user acting
 75	     *  under a delegation of the steward role (one covering the sheet's today) ends with for=<the steward
 76	     *  who delegated>. */
 77	    public synchronized void record(String entry) {
 78	        entry = entry + delegatedFor(entry);
 79	        List<String> holding = held.get();
 80	        if (holding != null) {
 81	            holding.add(entry);
 82	            return;
 83	        }
 84	        write(entry);
 85	    }
 86	
 87	    /** Run a change whose records are held back until it is done: written in order when it returns, dropped
 88	     *  when it throws (a refused change writes nothing to the audit). */
 89	    public <T> T held(java.util.function.Supplier<T> change) {
 90	        if (held.get() != null) {
 91	            return change.get();
 92	        }
 93	        List<String> holding = new ArrayList<>();
 94	        held.set(holding);
 95	        T result;
 96	        try {
 97	            result = change.get();
 98	        } finally {
 99	            held.remove();
100	        }
101	        for (String entry : holding) {
102	            write(entry);
103	        }
104	        return result;
105	    }
106	
107	    private synchronized void write(String entry) {
108	        try {
109	            Path parent = file.toAbsolutePath().getParent();
110	            if (parent != null) {
111	                Files.createDirectories(parent);
112	            }
113	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
114	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
115	        } catch (IOException e) {
116	            throw new UncheckedIOException(e);
117	        }
118	    }
119	
120	    /** " for=<steward>" when the record (EVENT sheet=<id> by=<user> ...) is a change by a delegated user. */
121	    private String delegatedFor(String entry) {
122	        String[] parts = entry.split(" ", 4);
123	        if (parts.length < 3 || REPORTS.contains(parts[0]) || !parts[1].startsWith("sheet=") || !parts[2].startsWith("by=")) {
124	            return "";
125	        }
126	        String delegator = settings.getObject().delegator(parts[1].substring("sheet=".length()), parts[2].substring("by=".length()));
127	        return delegator == null ? "" : " for=" + delegator;
128	    }
129	
130	    /** The sheet's lines exactly as the file holds them, newest first. With a name (compared trimmed and
131	     *  ignoring case) only the lines about that person: those carrying name=<the name> or person=<the name>. */
132	    public synchronized List<String> read(String sheetId, String name) {
133	        String who = name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
134	        List<String> lines = new ArrayList<>();
135	        if (!Files.exists(file)) {
136	            return lines;
137	        }
138	        List<String> all;
139	        try {
140	            all = Files.readAllLines(file, StandardCharsets.UTF_8);
141	        } catch (IOException e) {
142	            throw new UncheckedIOException(e);
143	        }
144	        String sheet = "sheet=" + sheetId;
145	        for (String line : all) {
146	            String[] parts = line.split(" ");
147	            if (parts.length < 2 || !parts[1].equals(sheet)) {
148	                continue;
149	            }
150	            if (!who.isEmpty() && !isAbout(parts, who)) {
151	                continue;
152	            }
153	            lines.add(line);
154	        }
155	        Collections.reverse(lines);
156	        return lines;
157	    }
158	
159	    /** A claim's timeline: the sheet's lines about one claim, newest first, exactly as the file holds them. With a
160	     *  number, the lines carrying number=<the number>; without one, the lines carrying none that name its person,
161	     *  amount and date together (person=, amount=, date=). */
162	    public List<String> timeline(String sheetId, String number, String person, String amount, String date) {
163	        List<String> found = new ArrayList<>();
164	        for (String line : read(sheetId, null)) {
165	            List<String> fields = List.of(line.split(" "));
166	            String numbered = null;
167	            for (String f : fields) {
168	                if (f.startsWith("number=")) numbered = f.substring("number=".length());
169	            }
170	            boolean about = number != null
171	                    ? number.equals(numbered)
172	                    : numbered == null && fields.contains("person=" + person) && fields.contains("amount=" + amount)
173	                            && fields.contains("date=" + date);
174	            if (about) found.add(line);
175	        }
176	        return found;
177	    }
178	
179	    private static boolean isAbout(String[] parts, String who) {
180	        for (int i = 2; i < parts.length; i++) {
181	            String p = parts[i];
182	            String value = p.startsWith("name=") ? p.substring(5) : p.startsWith("person=") ? p.substring(7) : null;
183	            if (value != null && value.trim().toLowerCase(Locale.ROOT).equals(who)) {
184	                return true;
185	            }
186	        }
187	        return false;
188	    }
189	
190	    /** Remove the audit file. */
191	    public synchronized void clear() {
192	        try {
193	            Files.deleteIfExists(file);
194	        } catch (IOException e) {
195	            throw new UncheckedIOException(e);
196	        }
197	    }
198	}
