277	    /** Whether any of the person's aliases is a name or alias on another sheet of the sheet's tree. */
278	    public boolean aliasClashes(String sheetId, long id) {
279	        for (String alias : jdbc.queryForList("SELECT alias FROM PUBLIC.person_alias WHERE sheet_id = ? AND person_id = ?",
280	                String.class, sheetId, id)) {
281	            if (takenInTree(sheetId, alias, id)) return true;
282	        }
283	        return false;
