    27	        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom,
    28	                !holds.isEmpty(), grades, holds, terms, contact, origin, retirements, tags, snapshots, statements, flag, approver);
    29	    }
