142	                    sheetId, periodId, personId);
143	        }, sheetId);
144	        for (Long periodId : lastRolloverPeriods(sheetId)) {
145	            jdbc.update("DELETE FROM period_pool_cut WHERE period_id = ? AND sheet_id = ?", periodId, sheetId);
146	            jdbc.update("DELETE FROM period_person_total WHERE period_id = ? AND sheet_id = ?", periodId, sheetId);
147	            jdbc.update("DELETE FROM period_opening WHERE period_id = ? AND sheet_id = ?", periodId, sheetId);
148	            jdbc.update("DELETE FROM period WHERE id = ? AND sheet_id = ?", periodId, sheetId);
