1	package net.officefloor.hq.app.period;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.util.Comparator;
6	import java.util.LinkedHashMap;
7	import java.util.List;
8	import java.util.Map;
9	import java.util.stream.Collectors;
10	import net.officefloor.hq.app.Audit;
11	import net.officefloor.hq.app.claim.Claim;
12	import net.officefloor.hq.app.claim.ClaimRepository;
13	import net.officefloor.hq.app.person.Hold;
14	import net.officefloor.hq.app.person.Person;
15	import net.officefloor.hq.app.person.PersonRepository;
16	import net.officefloor.hq.app.pool.Pool;
17	import net.officefloor.hq.app.pool.PoolMember;
18	import net.officefloor.hq.app.pool.PoolRepository;
19	import net.officefloor.hq.app.settings.SettingsRepository;
20	import org.springframework.stereotype.Service;
21	
22	/** Close an open period: fix its due-total as shown now (the dues now, late charges included, of the claims whose
23	 *  due-by falls in it that count by the status they had at the end of its last day, a person's open (OPEN or PENDING) claims dated
24	 *  within one of their holds left out unless bound by a statement, skipping those with none), so later changes to
25	 *  rates do not alter it; and each person's due-total for it likewise, for every person on the sheet (0.00 for one
26	 *  with nothing in it), and each person's carried figure for it (their claims that count whose due-by falls in a
27	 *  period ending before it starts and that were still OPEN or PENDING at the end of its last day, plus their opening
28	 *  balance for it, 0.00 for one with none); and every pool member's cut as it stands now, shown for the period from then on
29	 *  in place of its cut at the end of the period. Writes PERIOD_CLOSED, ending auto=yes when closed by the sheet's grace days. */
30	@Service
31	public class PeriodCloser {
32	
33	    private final PeriodRepository periods;
34	    private final ClaimRepository claims;
35	    private final PersonRepository people;
36	    private final SettingsRepository settings;
37	    private final PoolRepository pools;
38	    private final Audit audit;
39	
40	    public PeriodCloser(PeriodRepository periods, ClaimRepository claims, PersonRepository people,
41	            SettingsRepository settings, PoolRepository pools, Audit audit) {
42	        this.pools = pools;
43	        this.periods = periods;
44	        this.claims = claims;
45	        this.people = people;
46	        this.settings = settings;
47	        this.audit = audit;
48	    }
49	
50	    public Period close(String sheetId, String by, Period found, boolean auto) {
51	        return close(sheetId, by, found, auto, false);
52	    }
53	
54	    /** Close, or soft-close, a period (open or soft-closed), fixing its figures afresh. A soft close writes
55	     *  PERIOD_SOFT_CLOSED instead of PERIOD_CLOSED. */
56	    public Period close(String sheetId, String by, Period found, boolean auto, boolean soft) {
57	        LocalDate from = LocalDate.parse(found.from());
58	        LocalDate to = LocalDate.parse(found.to());
59	        String today = periods.today(sheetId);
60	        Map<Long, List<Hold>> holds = new java.util.HashMap<>();
61	        BigDecimal total = BigDecimal.ZERO.setScale(2);
62	        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
63	        Map<Long, BigDecimal> personCarried = new LinkedHashMap<>();
64	        List<Period> earlier = periods.list(sheetId).stream().filter(q -> LocalDate.parse(q.to()).isBefore(from)).toList();
65	        for (Person p : people.list(sheetId)) {
66	            personTotals.put(p.id(), BigDecimal.ZERO.setScale(2));
67	            personCarried.put(p.id(), BigDecimal.ZERO.setScale(2));
68	            holds.put(p.id(), p.liveHolds(today));
69	        }
70	        Map<Long, String> statusesThen = claims.statusesOn(sheetId, to);
71	        for (Claim c : claims.list(sheetId)) {
72	            String then = statusesThen.get(c.id());
73	            if (!c.countsAs(then, holds.getOrDefault(c.personId(), List.of()), today)) continue;
74	            LocalDate on = LocalDate.parse(c.dueBy());
75	            boolean in = !on.isBefore(from) && !on.isAfter(to);
76	            boolean carried = (then.equals("OPEN") || then.equals("PENDING")) && earlier.stream()
77	                    .anyMatch(q -> !on.isBefore(LocalDate.parse(q.from())) && !on.isAfter(LocalDate.parse(q.to())));
78	            if (!in && !carried) continue;
79	            BigDecimal now = claims.dueNow(sheetId, c);
80	            if (now == null) continue;
81	            if (in) {
82	                total = total.add(now);
83	                personTotals.merge(c.personId(), now, BigDecimal::add);
84	            }
85	            if (carried) personCarried.merge(c.personId(), now, BigDecimal::add);
86	        }
87	        Map<Long, BigDecimal> openings = periods.openings(sheetId, found.id());
88	        for (Map.Entry<Long, BigDecimal> e : openings.entrySet()) {
89	            if (personCarried.containsKey(e.getKey())) personCarried.merge(e.getKey(), e.getValue(), BigDecimal::add);
90	        }
91	        String shown = total.setScale(2).toPlainString();
92	        periods.close(sheetId, found.id(), total, personTotals, personCarried, soft);
93	        Map<String, Map<String, String>> cuts = new LinkedHashMap<>();
94	        for (Pool pool : pools.list(sheetId)) {
95	            Map<String, String> of = new LinkedHashMap<>();
96	            for (PoolMember m : pool.members()) of.put(m.key(), m.cut());
97	            cuts.put(pool.name(), of);
98	        }
99	        periods.fixPoolCuts(sheetId, found.id(), cuts);
100	        audit.record((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheetId + " by=" + by + " period=" + found.name() + " total=" + shown
101	                + (auto ? " auto=yes" : ""));
102	        return new Period(found.id(), found.name(), found.from(), found.to(), !soft, shown, personTotals.entrySet().stream().collect(Collectors.toMap(e -> Long.toString(e.getKey()),
103	                e -> e.getValue().setScale(2).toPlainString(), (a, b) -> a, LinkedHashMap::new)), personCarried.entrySet().stream().collect(Collectors.toMap(e -> Long.toString(e.getKey()),
104	                e -> e.getValue().setScale(2).toPlainString(), (a, b) -> a, LinkedHashMap::new)), soft, found.cap(),
105	                openings.entrySet().stream().collect(Collectors.toMap(e -> Long.toString(e.getKey()),
106	                e -> e.getValue().setScale(2).toPlainString(), (a, b) -> a, LinkedHashMap::new)), found.locked());
107	    }
108	
109	    /** Close, by the sheet's grace days (none when blank), every open (not closed nor soft-closed) period whose to-date plus the grace days is
110	     *  before the sheet's today, in order of their to-dates. */
111	    public void closeLapsed(String sheetId, String by, LocalDate today) {
112	        Integer grace = settings.graceDays(sheetId);
113	        if (grace == null) return;
114	        List<Period> lapsed = periods.list(sheetId).stream()
115	                .filter(p -> !p.closed() && !p.softClosed() && LocalDate.parse(p.to()).plusDays(grace).isBefore(today))
116	                .sorted(Comparator.comparing(Period::to)).toList();
117	        for (Period p : lapsed) close(sheetId, by, p, true);
118	    }
119	}
