    33	            throw new BadRequestException("no such person");
    34	        }
    35	        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
    36	            throw new BadRequestException("only a steward can undo a merge");
    37	        }
    38	        MergeRepository.Merge merge = merges.last(id, pid);
    39	        if (merge == null) {
    40	            throw new BadRequestException(into.name() + " has no merge to undo");
    41	        }
