    33	/** Add and open a claim per pasted line, in order, for the person on the sheet with that name (ignoring case).
    34	 *  A line naming a date and note that match one of the person's claims as they stood before the paste (not VOID or
    35	 *  DELETED; never a claim the paste itself added) updates the newest such DRAFT to the line's amount instead
    36	 *  (CLAIM_EDITED when it changes) and opens it; a line whose matches hold no DRAFT is refused. Every line is checked
    37	 *  first by the claim form's rules; each claim is then opened exactly as its open button would, in paste order
    38	 *  (unnumbered until settled). One change: any refusal (a line's, or an open's) refuses the whole paste — the store is rolled back and
    39	 *  no audit record is written. */
    40	public class PasteClaims {
    41	    private record Checked(Person person, PasteLine line, LocalDate date, Claim draft) {
    42	    }
    43	
    44	    /** Carries a refusal out of the transaction, which it rolls back. */
    45	    private static final class Refused extends RuntimeException {
    46	        final BadRequestException refusal;
    47	
    48	        Refused(BadRequestException refusal) {
    49	            super(refusal.getMessage(), null, false, false);
    50	            this.refusal = refusal;
    51	        }
    52	    }
    53	
    54	    public void paste(@PathVariable("sheetId") String sheetId, @Val PasteInput input,
    55	            ServerHttpConnection connection, PersonRepository people, ClaimRepository claims, SheetRepository sheets,
    56	            PeriodRepository periods, SettingsRepository settings, WatchRepository watches, Audit audit, Rollup rollup,
    57	            PlatformTransactionManager transactions, Out<PasteResult> result) throws BadRequestException {
    58	        String by = CurrentUser.require(connection);
    59	        String id = sheetId == null ? "" : sheetId.trim();
    60	        if (!people.sheetExists(id)) {
    61	            throw new BadRequestException("no such sheet");
    62	        }
    63	        TransactionTemplate transaction = new TransactionTemplate(transactions);
    64	        try {
    65	            result.set(audit.held(() -> transaction.execute(status -> {
    66	                try {
    67	                    return apply(id, by, input, people, claims, sheets, periods, settings, watches, audit, rollup);
    68	                } catch (BadRequestException e) {
    69	                    throw new Refused(e);
    70	                }
    71	            })));
    72	        } catch (Refused e) {
    73	            throw e.refusal;
    74	        }
    75	    }
    76	
    77	    private static PasteResult apply(String id, String by, PasteInput input, PersonRepository people, ClaimRepository claims,
    78	            SheetRepository sheets, PeriodRepository periods, SettingsRepository settings, WatchRepository watches,
    79	            Audit audit, Rollup rollup) throws BadRequestException {
    80	        LocalDate entry = sheets.entryDate(id);
    81	        List<Checked> checked = new ArrayList<>();
    82	        Set<String> refs = new HashSet<>();
    83	        // Each person's claims as they stood before the paste, newest first.
    84	        Map<Long, List<Claim>> before = new HashMap<>();
    85	        Set<Long> taken = new HashSet<>();
    86	        int n = 0;
    87	        for (PasteLine line : input.lines()) {
    88	            n++;
    89	            try {
    90	                Person person = people.findByName(id, line.name());
    91	                if (person == null) {
    92	                    throw new BadRequestException("no one on the sheet is named " + line.name());
    93	                }
    94	                LocalDate date = line.claim().date() != null ? line.claim().date() : entry;
    95	                List<Claim> theirs = before.computeIfAbsent(person.id(), pid -> claims.ofPerson(id, pid));
    96	                String note = line.claim().note() == null ? "" : line.claim().note().trim();
    97	                boolean matched = false;
    98	                Claim draft = null;
    99	                for (Claim c : theirs) {
   100	                    if (c.status().equals("VOID") || c.status().equals("DELETED") || !c.date().equals(date.toString())
   101	                            || !(c.note() == null ? "" : c.note().trim()).equals(note)) {
   102	                        continue;
   103	                    }
   104	                    matched = true;
   105	                    if (c.status().equals("DRAFT") && !taken.contains(c.id())) {
   106	                        draft = c;
   107	                        break;
   108	                    }
   109	                }
   110	                if (matched && draft == null) {
   111	                    throw new BadRequestException(person.name() + " has no draft claim of " + date + " with that note to update");
   112	                }
   113	                if (draft != null) {
   114	                    taken.add(draft.id());
   115	                }
   116	                PeriodGuard.open(periods, id, draft != null ? LocalDate.parse(draft.dueBy()) : claims.dueBy(id, person.id(), date));
   117	                people.claimAllowed(id, person.id(), date);
   118	                line.claim().checkCorrection(claims, id, person.id(), draft == null ? null : draft.id());
   119	                line.claim().checkRef(claims, id, draft == null ? null : draft.id());
   120	                if (line.claim().ref() != null && !refs.add(line.claim().ref().toLowerCase(Locale.ROOT))) {
   121	                    throw new BadRequestException("reference " + line.claim().ref() + " is given twice in the paste");
   122	                }
   123	                checked.add(new Checked(person, line, date, draft));
   124	            } catch (BadRequestException e) {
   125	                throw new BadRequestException("line " + n + ": " + e.getMessage());
   126	            }
   127	        }
   128	        n = 0;
   129	        for (Checked c : checked) {
   130	            n++;
   131	            try {
   132	                long cid;
   133	                if (c.draft() != null) {
   134	                    cid = c.draft().id();
   135	                    ClaimAmountEdit.apply(id, cid, c.line().claim().amount(), by, claims, periods, audit, rollup);
   136	                } else {
   137	                    Rollup.Snapshot was = rollup.take(id);
   138	                    Claim added = claims.add(id, c.person().id(), c.line().claim().amount(), c.date(), c.line().claim().note(), null, c.line().claim().ref());
   139	                    claims.log(id, added.id(), by);
   140	                    audit.record("CLAIM_ADDED sheet=" + id + " by=" + by + " person=" + c.person().name()
   141	                            + " amount=" + added.amount() + " date=" + added.date() + Claim.auditRef(added.ref()));
   142	                    if (added.lateEntry()) {
   143	                        audit.record("LATE_ENTRY sheet=" + id + " by=" + by + " person=" + c.person().name()
   144	                                + " amount=" + added.amount() + " date=" + added.date());
   145	                    }
   146	                    rollup.record(id, by, was);
   147	                    cid = added.id();
   148	                }
   149	                ClaimStatusChange.open(id, cid, by, claims, periods, settings, audit, rollup, watches);
   150	            } catch (BadRequestException e) {
   151	                throw new BadRequestException("line " + n + ": " + e.getMessage());
   152	            }
   153	        }
   154	        return new PasteResult(checked.size());
   155	    }
   156	}
