    14	/** Bind the paste box: each non-blank line is name,amount,date,note — the name is required (trimmed), the
    15	 *  amount and date follow the claim form's rules (a blank date: the sheet's entry date, else its today), and the note is the rest
    16	 *  of the line (it may hold commas, or be absent); a note ending in " #<reference>" gives the claim that external reference. A paste with no lines is refused. */
    17	public class ValidatePaste {
    18	    /** A note ending in " #<reference>": the note before it, and the reference. */
    19	    private static final Pattern REF = Pattern.compile("(.*) #(\\S.*)");
    20	
    21	    public void validate(@RequestBody PasteRequest request, Out<PasteInput> paste) throws BadRequestException {
    22	        String text = request == null || request.text() == null ? "" : request.text();
    23	        List<PasteLine> lines = new ArrayList<>();
    24	        int n = 0;
    25	        for (String raw : text.split("\r?\n", -1)) {
    26	            n++;
    27	            if (raw.isBlank()) {
    28	                continue;
    29	            }
    30	            String[] f = raw.split(",", 4);
    31	            String name = f[0].trim();
    32	            String amount = f.length > 1 ? f[1].trim() : "";
    33	            String date = f.length > 2 ? f[2].trim() : "";
    34	            String note = f.length > 3 ? f[3].trim() : "";
    35	            String ref = null;
    36	            Matcher tail = REF.matcher(note);
    37	            if (tail.matches()) {
    38	                note = tail.group(1).trim();
    39	                ref = tail.group(2).trim();
    40	            }
    41	            if (name.isEmpty()) {
    42	                throw new BadRequestException("line " + n + ": name is required");
    43	            }
    44	            LocalDate on = null;
    45	            if (!date.isEmpty()) {
    46	                try {
    47	                    on = LocalDate.parse(date);
    48	                } catch (DateTimeParseException e) {
    49	                    throw new BadRequestException("line " + n + ": date must be yyyy-mm-dd");
    50	                }
    51	            }
    52	            try {
    53	                lines.add(new PasteLine(name, new ClaimInput(ClaimInput.signedAmount(amount), on, note, null, ref, null)));
    54	            } catch (BadRequestException e) {
    55	                throw new BadRequestException("line " + n + ": " + e.getMessage());
    56	            }
    57	        }
    58	        if (lines.isEmpty()) {
    59	            throw new BadRequestException("paste at least one line");
    60	        }
    61	        paste.set(new PasteInput(lines));
    62	    }
    63	}
