 46	async function send<T>(path: string, init?: RequestInit, asOf = asOfDate, preview = ''): Promise<T> {
 47	  const headers = new Headers(init?.headers);
 48	  if (signedInUser) headers.set('X-User', signedInUser);
 49	  if (asOf) headers.set('X-As-Of', asOf);
 50	  if (preview) headers.set('X-Preview', preview);
 51	  const res = await fetch(path, { ...init, headers });
 52	  if (!res.ok) {
 53	    let message = `${init?.method ?? 'GET'} ${path} -> ${res.status}`;
 54	    try {
 55	      const body = (await res.json()) as { error?: string };
 56	      if (body?.error) message = body.error;
 57	    } catch {
 58	      /* no JSON body: keep the status message */
 59	    }
 60	    throw new HttpError(message, res.status);
 61	  }
 62	  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
 63	}
