5	/** A grade's rate: a percent with two decimals, in force from its from-date (yyyy-mm-dd; null when it
6	 *  applies from the beginning of time) through its to-date (null when it has no end), and its `version`: how many versions the grade's rate from that
7	 *  from-date has had (this is the newest, the one in force). `level` is the sheet it
8	 *  is set on: 0 this sheet, 1 its parent, 2 the parent's parent, 3 the one above that. `after`: for a forward-only
9	 *  rate (saved with a from-date on or after the sheet's today), the claim-added number it was saved at — it applies
10	 *  only to claims added after it (see `Claim.added`); null when it applies to every claim. `superseded`: an older
11	 *  version, kept only for the claims a newer forward-only version does not apply to (never shown, never in force). */
12	export type Rate = {
13	  grade: string; pct: string; from: string | null; to: string | null; version?: number; level?: number;
14	  after?: number | null; superseded?: boolean;
15	};
16	
17	export function ratesKey(sheetId: string) {
18	  return ['sheet', sheetId, 'rates'];
19	}
20	
21	/** The sheet's rates (level 0), by grade then from-date (an undated rate first); a grade with no rate is not
22	 *  listed. Then those of the sheets its grades fall back to, nearest first (level 1 its parent, up to 3). Then the
23	 *  older (superseded) versions of all of them, for the claims they still apply to. */
24	export function useRates(sheetId: string) {
25	  const read = useReader();
26	  return useQuery({
27	    queryKey: read.key(ratesKey(sheetId)),
28	    queryFn: async () => {
29	      const got = await read.get<{ rates: Rate[]; inherited: Rate[][]; earlier: Rate[]; inheritedEarlier: Rate[][] }>(
30	        `/api/sheets/${encodeURIComponent(sheetId)}/rates`);
31	      return [
32	        ...got.rates.map((r) => ({ ...r, level: 0 })),
33	        ...(got.inherited ?? []).flatMap((rates, i) => rates.map((r) => ({ ...r, level: i + 1 }))),
34	        ...(got.earlier ?? []).map((r) => ({ ...r, level: 0, superseded: true })),
35	        ...(got.inheritedEarlier ?? []).flatMap((rates, i) => rates.map((r) => ({ ...r, level: i + 1, superseded: true }))),
36	      ];
37	    },
38	  });
39	}
40	
41	/** The rate (a two-decimal percent) for a grade in force on a date (yyyy-mm-dd): on this sheet, the one with
42	 *  the latest from-date on or before it, an undated rate applying from the beginning of time, unless the date is
43	 *  after that rate's to-date; when this sheet has none in force, its parent's the same way, then the parent's
44	 *  parent's, up to three levels up; undefined when none applies.
45	 *
46	 *  Given a claim's added number (`added`, see `Claim.added`), the rate that claim takes: the same way, among only
47	 *  the rate versions that apply to it — those that apply to every claim and the forward-only ones saved before it
48	 *  was added — the newest of each from-date. Without one, the rate in force, whatever claim it is for. */
49	export function rateFor(rates: Rate[] | undefined, grade: string | undefined, on: string | undefined,
50	  added?: number): string | undefined {
51	  if (on === undefined) return undefined;
52	  for (let level = 0; level <= 3; level++) {
53	    let found: Rate | undefined;
54	    for (const r of rates ?? []) {
55	      if ((r.level ?? 0) !== level || r.grade !== grade || (r.from !== null && r.from > on)) continue;
56	      if (added === undefined ? r.superseded : r.after != null && r.after >= added) continue;
57	      if (found === undefined || (found.from ?? '') < (r.from ?? '')
58	        || ((found.from ?? '') === (r.from ?? '') && (found.version ?? 0) < (r.version ?? 0))) found = r;
59	    }
60	    if (found !== undefined && (found.to == null || found.to >= on)) return found.pct;
61	  }
62	  return undefined;
63	}
