65	/** A two-decimal number as a whole count of hundredths ("12.50" -> 1250, "-0.30" -> -30). */
66	export function hundredths(v: string): bigint {
67	  const t = v.trim();
68	  const negative = t.startsWith('-');
69	  const [whole, frac = ''] = (negative ? t.slice(1) : t).split('.');
70	  const cents = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
71	  return negative ? -cents : cents;
72	}
73	
74	/** A whole count of hundredths as a two-decimal number (-30 -> "-0.30"). */
75	export function money(cents: bigint): string {
76	  const abs = cents < 0n ? -cents : cents;
77	  return `${cents < 0n ? '-' : ''}${abs / 100n}.${(abs % 100n).toString().padStart(2, '0')}`;
78	}
79	
80	/** A rate figure: an amount (two decimals) times a rate (a two-decimal percent), divided by 100, rounded
81	 *  half up (when `halfUp`) or half to even to two decimals — not floored (see `atLeast`); 'n/a' when there is
82	 *  no rate. Worked in whole numbers, so exact. */
83	export function due(amount: string, pct: string | undefined, halfUp: boolean): string {
84	  if (pct === undefined) return 'n/a';
85	  return money(percentOf(amount, pct, 1n, halfUp));
86	}
87	
88	/** A holder's part of a claim: its amount (two decimals) times a share (a two-decimal percent) divided by 100, times
89	 *  a rate (a two-decimal percent) divided by 100, rounded half up (when `halfUp`, away from zero) or half to even to
90	 *  two decimals; 'n/a' when there is no rate. Worked in whole numbers, so exact. */
91	export function heldPart(amount: string, share: string, pct: string | undefined, halfUp: boolean): string {
92	  if (pct === undefined) return 'n/a';
93	  const signed = hundredths(amount) * hundredths(share) * hundredths(pct); // in 1/1_000_000 of a unit, before the two divisions by 100
94	  const product = signed < 0n ? -signed : signed;
95	  const rest = product % 100000000n;
96	  let cents = product / 100000000n;
97	  if (rest > 50000000n || (rest === 50000000n && (halfUp || cents % 2n === 1n))) cents += 1n;
98	  return money(signed < 0n ? -cents : cents);
99	}
100	
101	/** A figure (two decimals) raised to at least a floor (two decimals; none when undefined); 'n/a' stays 'n/a'. */
102	export function atLeast(figure: string, floor: string | undefined): string {
103	  if (figure === 'n/a' || floor === undefined || hundredths(figure) >= hundredths(floor)) return figure;
104	  return money(hundredths(floor));
105	}
106	
107	/** Whether an amount (two decimals) is a correction's: below zero. */
108	export function isCorrection(amount: string): boolean {
109	  return hundredths(amount) < 0n;
110	}
111	
112	/** An amount (two decimals) times a rate (a two-decimal percent) times a whole number, divided by
113	 *  100, rounded half up (when `halfUp`, away from zero) or half to even, in hundredths (a negative amount rounds as its size does, then takes
114	 *  its sign back). */
115	function percentOf(amount: string, pct: string, times: bigint, halfUp: boolean): bigint {
116	  const signed = hundredths(amount) * hundredths(pct) * times; // in 1/1_000_000 of a unit
117	  const product = signed < 0n ? -signed : signed;
118	  const rest = product % 10000n;
119	  let cents = product / 10000n;
120	  if (rest > 5000n || (rest === 5000n && (halfUp || cents % 2n === 1n))) cents += 1n;
121	  return signed < 0n ? -cents : cents;
122	}
123	
124	/** A figure (two decimals) with a late charge added on top: for each full 30 days, the late percent
125	 *  (two decimals) in force on that boundary of the figure plus the charges of the boundaries before it (compounding), each rounded like a due, the charges added up;
126	 *  'n/a' stays 'n/a'. */
127	export function withCharge(figure: string, latePcts: string[], halfUp: boolean): string {
128	  if (figure === 'n/a') return figure;
129	  return money(latePcts.reduce((sum, pct) => sum + percentOf(money(sum), pct, 1n, halfUp), hundredths(figure)));
130	}
131	
132	/** Dues added up, skipping 'n/a'. */
133	export function sumDues(dues: string[]): string {
134	  return money(dues.filter((d) => d !== 'n/a').reduce((sum, d) => sum + hundredths(d), 0n));
135	}
136	
137	/** A sheet's total of people's figures: added up, skipping 'n/a', but leaving out the single highest
138	 *  and the single lowest figure when three or more people have one. */
139	export function trimmedSum(figures: string[]): string {
140	  const cents = figures.filter((d) => d !== 'n/a').map(hundredths).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
141	  const kept = cents.length >= 3 ? cents.slice(1, -1) : cents;
142	  return money(kept.reduce((sum, c) => sum + c, 0n));
143	}
