24	/** Each person's excess, by person id: how far the sum of their figures plus their cut total is above the sheet's cap; 0.00 when
25	 *  it is not (or there is no cap, or their due-total is 'n/a'). */
26	export function useExcess(sheetId: string): Map<number, string> {
27	  const excess = new Map<number, string>();
28	  for (const [id, f] of useDueFigures(sheetId)) excess.set(id, f.excess);
29	  return excess;
30	}
