33	 *  claims, and of their counting open (OPEN or PENDING) claims, as in their due-total ('n/a' figures skipped).
34	 *  The two add up to the due-total before the cap. */
35	export function useSettledOpenTotals(sheetId: string): Map<number, { settled: string; open: string }> {
36	  const split = new Map<number, { settled: string; open: string }>();
37	  for (const [id, f] of useDueFigures(sheetId)) split.set(id, { settled: f.settled, open: f.open });
38	  return split;
