49	/** Each person's due-total held to the cap, their excess over it, its settled and open parts, and the settled
50	 *  figures their score counts. */
51	function useDueFigures(sheetId: string): Map<number, { total: string; excess: string; settled: string; open: string; scored: string }> {
52	  const people = usePeople(sheetId);
53	  const claims = useClaims(sheetId);
54	  const rates = useRates(sheetId);
55	  const today = useSheetToday(sheetId);
56	  const settings = useSettings(sheetId).data;
57	  const cuts = useCutTotals(sheetId);
58	  return dueFigures(people.data, claims.data, rates.data, settings, today.data?.today, cuts);
