69	function dueFigures(
70	  people: Person[] | undefined,
71	  claims: Claim[] | undefined,
72	  rates: Rate[] | undefined,
73	  settings: Settings | undefined,
74	  today: string | undefined,
75	  cuts?: Map<number, string>,
76	): Map<number, { total: string; excess: string; settled: string; open: string; scored: string }> {
77	  const holds = holdsById(people, today);
78	  const totals = new Map<number, { total: string; excess: string; settled: string; open: string; scored: string }>();
79	  // Each counting claim's due now, by claim id, at its own person's grade.
80	  const byId = new Map((people ?? []).map((p) => [p.id, p]));
81	  const dueOf = new Map<number, string>();
82	  for (const c of claims ?? []) {
83	    const owner = byId.get(c.personId);
84	    if (owner === undefined || !counts(c, holds, today)) continue;
85	    dueOf.set(c.id, claimDueNow(c, claims, rateFor(rates, gradeOn(owner, c.date), c.date, c.added), settings, today, gradeOn(owner, c.date)));
86	  }
87	  // A holder's part of a claim, at the rate of their own grade in force on its date ('n/a' when none: 0.00).
88	  const partOf = (c: Claim, s: ClaimShare): string => {
89	    const holder = byId.get(s.personId);
90	    const grade = holder === undefined ? undefined : gradeOn(holder, c.date);
91	    return sharePart(c, s.share, rateFor(rates, grade, c.date, c.added), roundsHalfUp(c, claims, settings, today));
92	  };
93	  for (const p of people ?? []) {
94	    const own = (claims ?? []).filter((c) => c.personId === p.id && dueOf.has(c.id));
95	    // A shared claim's own person counts its due less its holders' parts; each holder counts their part.
96	    const ownDues = own.map((c) => {
97	      const d = dueOf.get(c.id)!;
98	      if (d === 'n/a' || c.shares.length === 0) return d;
99	      return money(hundredths(d) - c.shares.reduce((sum, s) => {
100	        const part = partOf(c, s);
101	        return sum + (part === 'n/a' ? 0n : hundredths(part));
102	      }, 0n));
103	    });
104	    const held = (claims ?? []).filter((c) => c.personId !== p.id && dueOf.has(c.id) && dueOf.get(c.id) !== 'n/a'
105	      && c.shares.some((s) => s.personId === p.id));
106	    const counting = [...own, ...held];
107	    const dues = [...ownDues, ...held.map((c) => partOf(c, c.shares.find((s) => s.personId === p.id)!))];
108	    const rated = rateFor(rates, p.grade, today) !== undefined;
109	    const shown = rated || own.some((c) => fixedDue(c) !== null && fixedDue(c) !== 'n/a') || dues.some((d) => d !== 'n/a');
110	    const sum = sumDues(dues);
111	    // The cap in force on the date of their latest counting claim (on the sheet's today when they have none).
112	    const latest = own.reduce<string | undefined>((at, c) => (at === undefined || c.date > at ? c.date : at), undefined);
113	    const cap = settingOn(settings, 'cap', latest ?? today);
114	    // The cap covers the due-total and the cut total together: the due-total is held to the cap less the cut.
115	    const cut = hundredths(cuts?.get(p.id) ?? '0.00');
116	    const room = cap === null ? 0n : hundredths(cap) - cut > 0n ? hundredths(cap) - cut : 0n;
117	    const over = shown && cap !== null && hundredths(sum) > room;
118	    totals.set(p.id, {
119	      total: !shown ? 'n/a' : over ? money(room) : sum,
120	      excess: over ? money(hundredths(sum) - room) : '0.00',
121	      settled: sumDues(dues.filter((_, i) => counting[i].status === 'SETTLED')),
122	      open: sumDues(dues.filter((_, i) => counting[i].status !== 'SETTLED')),
123	      scored: sumDues(own.filter((c) => c.status === 'SETTLED' && c.corrects === null).map((c) => dueOf.get(c.id)!)),
124	    });
125	  }
126	  return totals;
127	}
