7	/** The day (yyyy-mm-dd) a claim's overdue days count from: its due-by plus the grace days, in force on the claim's
8	 *  date, of the grade its person had on that date (`grade`); its due-by when that grade has none then. */
9	export function overdueFrom(c: Claim, settings: Settings | undefined, grade: string | undefined): string {
10	  const grace = grade === undefined ? null : settingOn(settings, `grace-${grade}`, c.date);
11	  if (grace === null || grace === '') return c.dueBy;
12	  return new Date(Date.parse(`${c.dueBy}T00:00:00Z`) + Number(grace) * 86_400_000).toISOString().slice(0, 10);
13	}
14	
15	/** Whether a claim is overdue: it is open (OPEN or PENDING), not deferred, and its overdue-from day (see
16	 *  `overdueFrom`; `grade` is the grade its person had on its date) is before the sheet's today. */
17	export function isOverdue(c: Claim, today: string, settings: Settings | undefined, grade: string | undefined): boolean {
18	  return isOpen(c) && !isDeferred(c, today) && overdueFrom(c, settings, grade) < today;
19	}
20	
21	/** Whether a claim's live figures (its rate step and late charge) round half up: by the sheet's rounding
22	 *  mode in force on the claim's date (half-up or half-even) when there is one; else when the claim is
23	 *  dated before the sheet's policy date (blank meaning the sheet's today); else they round half to
24	 *  even. A correction rounds by the date of the claim it corrects (its person's claim with that
25	 *  number), not its own. Half to even until the settings and the sheet's today are loaded. */
26	export function roundsHalfUp(c: Claim, claims: Claim[] | undefined, settings: Settings | undefined, today: string | undefined): boolean {
27	  const corrected = c.corrects === null
28	    ? undefined
29	    : (claims ?? []).find((o) => o.personId === c.personId && o.number === c.corrects);
30	  const date = corrected?.date ?? c.date;
31	  const mode = settingOn(settings, 'rounding', date);
32	  if (mode === 'half-up') return true;
33	  if (mode === 'half-even') return false;
34	  const policy = settings === undefined ? undefined : settings.policyDate ?? today;
35	  if (policy === undefined) return false;
36	  return date < policy;
37	}
