39	/** A claim's due now: a settled claim's frozen due; else the due as shown its last statement bound it to (late
40	 *  charge and floor included: while bound, its charge no longer follows the sheet's today); else its floored figure — the greater of the floor (two decimals; none
41	 *  while it is not loaded) and its live rate figure — plus,
42	 *  while it is overdue, for every full 30 days it is overdue the sheet's late percent in force on that boundary
43	 *  date (the overdue-from day — the due-by plus the grade's grace — plus 30, 60, 90 ... days) of that figure plus the charges of the boundaries before it (compounding), each rounded like a due, the charges added up. A
44	 *  correction (a negative amount) has no floor and no late charge, nor does a claim whose late charge a steward waived. No charge until the settings and the sheet's today are loaded. */
45	export function dueNow(c: Claim, figure: string, floor: string | undefined, settings: Settings | undefined,
46	  today: string | undefined, halfUp: boolean, grade: string | undefined): string {
47	  if (c.due !== null || fixedDue(c) !== null || figure === 'n/a' || isCorrection(c.amount)) return figure;
48	  const pcts: string[] = [];
49	  if (!c.waived && settings !== undefined && today !== undefined && isOverdue(c, today, settings, grade)) {
50	    const dueBy = Date.parse(`${overdueFrom(c, settings, grade)}T00:00:00Z`);
51	    const periods = Math.floor((Date.parse(`${today}T00:00:00Z`) - dueBy) / 86_400_000 / 30);
52	    for (let n = 1; n <= periods; n++) {
53	      const boundary = new Date(dueBy + n * 30 * 86_400_000).toISOString().slice(0, 10);
54	      pcts.push(settingOn(settings, 'late-pct', boundary) ?? '0.00');
55	    }
56	  }
57	  return withCharge(atLeast(figure, floor), pcts, halfUp);
58	}
59	
60	/** A claim's due now (see `dueNow`) from its fixed figure, else its live rate figure at this rate (a
61	 *  two-decimal percent; undefined when none applies), with the floor in force on its date, every rounding by
62	 *  the claim's policy (see `roundsHalfUp`) — the other claims on the sheet are what a correction is looked up in.
63	 *  No floor until the settings are loaded. */
64	export function claimDueNow(c: Claim, claims: Claim[] | undefined, pct: string | undefined,
65	  settings: Settings | undefined, today: string | undefined, grade: string | undefined): string {
66	  const up = roundsHalfUp(c, claims, settings, today);
67	  const floor = settings === undefined ? undefined : settingOn(settings, 'floor', c.date) ?? undefined;
68	  return dueNow(c, fixedDue(c) ?? due(c.amount, pct, up), floor, settings, today, up, grade);
69	}
