71	/** Each person's overdue figures, by person id: how many of their claims that count are overdue, and
72	 *  the sum of those claims' dues now (a stated claim's bound figure, else its live due, with its late
73	 *  charge), skipping
74	 *  those with none. Empty until the terms and the sheet's today are loaded. */
75	export function useOverdue(sheetId: string): Map<number, { count: number; total: string }> {
76	  const people = usePeople(sheetId);
77	  const claims = useClaims(sheetId);
78	  const rates = useRates(sheetId);
79	  const settings = useSettings(sheetId).data;
80	  const today = useSheetToday(sheetId).data?.today;
81	  const holds = holdsById(people.data, today);
82	  const figures = new Map<number, { count: number; total: string }>();
83	  if (settings === undefined || today === undefined) return figures;
84	  for (const p of people.data ?? []) {
85	    const overdue = (claims.data ?? []).filter(
86	      (c) => c.personId === p.id && counts(c, holds, today) && isOverdue(c, today, settings, gradeOn(p, c.date)),
87	    );
88	    figures.set(p.id, {
89	      count: overdue.length,
90	      total: sumDues(overdue.map((c) =>
91	        claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(p, c.date), c.date, c.added), settings, today, gradeOn(p, c.date)))),
92	    });
93	  }
94	  return figures;
95	}
