 71	/** The role a user acts in on the sheet: steward while a delegation to them covers the sheet's today, else
 72	 *  their own role (undefined when none is set: a clerk). */
 73	export function roleOf(settings: Settings | undefined, user: string | undefined, today: string | undefined): string | undefined {
 74	  if (today !== undefined && settings?.delegations?.some((d) => d.user === user && d.from <= today && today <= d.to)) return 'steward';
 75	  return settings?.roles.find((r) => r.user === user)?.role;
 76	}
