 78	/** The policy version in force on a date: the number of the sheet's policy versions whose from-date is on or before
 79	 *  it (one with no from-date counts always). */
 80	export function policyVersionOn(settings: Settings, date: string): number {
 81	  return (settings.policyVersions ?? []).filter((from) => from === null || from <= date).length;
 82	}
