286	   137	    /** Each member's cut of the pot (null for a member that is not current). A member with a cut is one current,
287	   138	     *  neither retired nor held on the sheet's today;
288	   139	     *  each such member's cut is the pot times their share divided by the shares of the members with a cut added
289	   140	     *  up, rounded half to even to two decimals (0.00 for any other member, and for every member when none has a
290	   141	     *  cut); the remainder, the pot minus the cuts added up, goes to the member with the smallest non-zero cut
291	   142	     *  (the latest added on a tie; a member with no cut gets none), or when no cut is non-zero to the last member
292	   143	     *  with a share, so the cuts total exactly the pot. */
293	   144	    private static List<PoolMember> cut(List<PoolMember> members, BigDecimal pot, Set<Long> held) {
294	   145	        List<Boolean> withCut = new ArrayList<>();
295	   146	        BigDecimal shares = BigDecimal.ZERO;
296	   147	        for (PoolMember m : members) {
297	   148	            boolean has = m.current() && !m.retired() && (m.personId() == null || !held.contains(m.personId()));
298	   149	            withCut.add(has);
299	   150	            if (has) shares = shares.add(new BigDecimal(m.share()));
300	   151	        }
301	   152	        List<BigDecimal> cuts = new ArrayList<>();
302	   153	        int smallest = -1;
303	   154	        int lastWithShare = -1;
304	   155	        BigDecimal sum = BigDecimal.ZERO;
305	   156	        for (int i = 0; i < members.size(); i++) {
306	   157	            PoolMember m = members.get(i);
307	   158	            boolean has = withCut.get(i) && shares.signum() > 0;
308	   159	            BigDecimal share = has ? new BigDecimal(m.share()) : BigDecimal.ZERO;
309	   160	            BigDecimal cut = has ? pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN)
310	   161	                    : BigDecimal.ZERO.setScale(2);
311	   162	            cuts.add(cut);
312	   163	            sum = sum.add(cut);
313	   164	            if (has && share.signum() > 0) lastWithShare = i;
314	   165	            if (has && cut.signum() != 0 && (smallest < 0 || cut.compareTo(cuts.get(smallest)) <= 0)) {
315	   166	                smallest = i;
316	   167	            }
317	   168	        }
318	   169	        int to = smallest >= 0 ? smallest : lastWithShare;
319	   170	        if (to >= 0) cuts.set(to, cuts.get(to).add(pot.subtract(sum)));
320	   171	        List<PoolMember> cut = new ArrayList<>();
321	   172	        for (int i = 0; i < members.size(); i++) {
322	   173	            PoolMember m = members.get(i);
323	   174	            cut.add(new PoolMember(m.personId(), m.pool(), m.name(), m.share(), m.retired(),
324	   175	                    m.current() ? cuts.get(i).setScale(2).toPlainString() : null, m.from(), m.to(), m.current()));
325	   176	        }
326	   177	        return cut;
327	   178	    }
