440	   291	    /** The named pool with its cuts, resolving the pool above it first for its pot. */
441	   292	    private static Pool resolve(String name, Map<String, List<PoolMember>> members, Map<String, String> parents,
442	   293	            BigDecimal sheetPot, Set<Long> held, Map<String, Pool> done) {
443	   294	        Pool known = done.get(name);
444	   295	        if (known != null) return known;
445	   296	        BigDecimal pot = sheetPot;
446	   297	        String parent = parents.get(name);
447	   298	        if (parent != null) {
448	   299	            pot = null;
449	   300	            if (members.containsKey(parent)) {
450	   301	                for (PoolMember m : resolve(parent, members, parents, sheetPot, held, done).members()) {
451	   302	                    if (name.equals(m.pool()) && m.cut() != null) pot = new BigDecimal(m.cut());
452	   303	                }
453	   304	            }
454	   305	        }
455	   306	        List<PoolMember> of = members.get(name);
456	   307	        BigDecimal total = of.stream().filter(PoolMember::current).map(m -> new BigDecimal(m.share()))
457	   308	                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
458	   309	        boolean balanced = total.compareTo(HUNDRED) == 0;
459	   310	        boolean allRetired = of.stream().filter(PoolMember::current).allMatch(PoolMember::retired);
460	   311	        Pool pool = new Pool(name, balanced && pot != null && !allRetired ? cut(of, pot, held) : of,
461	   312	                total.toPlainString(), balanced, 0);
462	   313	        done.put(name, pool);
463	   314	        return pool;
464	   315	    }
