16	/** The sheet's people: a form that adds a person, or edits one when their editor is open, and the
17	 *  list of everyone in list order (by position; new people go to the end) (retired people only when "show retired" is on), each
18	 *  with the grade in force on the sheet's today. An edit records the form's grade from its from-date
19	 *  (blank: the sheet's today); the first grade a person is given applies from the beginning of time.
20	 *  A person may have their own terms (days; blank for none), dated by the terms from-date (blank: from the
21	 *  beginning of time; a dated save keeps the others), the ones in force on the sheet's today shown on their row:
22	 *  a claim's due-by is fixed when it is created from those in force on its date, ahead of their grade's and the
23	 *  sheet's terms. A person may have a contact
24	 *  (stored trimmed and lower-cased; blank for none), shown on their row; another person's contact is refused.
25	 *  A person may carry tags (comma separated; trimmed, lower-cased, repeats dropped), shown sorted on their row.
26	 *  The editor remembers the version of the person it loaded; when someone else has saved them since,
27	 *  the save is refused (409) and the editor shows their current values, at their current version; any other
28	 *  refused edit closes the editor, leaving its error showing. Each person is a <tbody> so features can add
29	 *  cells and rows of their own to it (slots/defs/personRow). A quick-add bar takes a name and an amount
30	 *  and adds a draft claim for that person (adding them with the sheet's default grade, A when blank, when the name is new) in one change.
31	 *  A restricted user's list shows only the people of their crews (see `useVisiblePeople`), and the people
32	 *  they added on this screen (by either form) until a sheet is loaded again. */
33	const SORTS = ['added', 'name', 'grade', 'due-total'] as const;
34	type SortKey = (typeof SORTS)[number];
35	const asSort = (raw: unknown): SortKey => {
36	  const s = asString(raw);
37	  return (SORTS as readonly string[]).includes(s) ? (s as SortKey) : 'added';
38	};
