40	/** Names compare trimmed and ignoring case. */
41	const nameKey = (name: string) => name.trim().toLowerCase();
42	
43	/** The people in the order the screen shows them (URL key `sortBy`, this user's screen only): list order
44	 *  ('added'), or by name (as names are compared), grade, or due-total (lowest first, 'n/a' last). The sort
45	 *  is stable, so equal keys keep list order; it changes nothing else (positions, rollups, actions). */
46	function sortPeople(people: Person[], by: SortKey, dueTotals: Map<number, string>): Person[] {
47	  if (by === 'added') return people;
48	  const cmp = (a: Person, b: Person): number => {
49	    if (by === 'name') {
50	      const x = nameKey(a.name);
51	      const y = nameKey(b.name);
52	      return x < y ? -1 : x > y ? 1 : 0;
53	    }
54	    if (by === 'grade') return a.grade < b.grade ? -1 : a.grade > b.grade ? 1 : 0;
55	    const x = dueTotals.get(a.id);
56	    const y = dueTotals.get(b.id);
57	    const xn = x === undefined || x === 'n/a';
58	    const yn = y === undefined || y === 'n/a';
59	    if (xn || yn) return xn === yn ? 0 : xn ? 1 : -1;
60	    const xc = hundredths(x);
61	    const yc = hundredths(y);
62	    return xc < yc ? -1 : xc > yc ? 1 : 0;
63	  };
64	  return [...people].sort(cmp);
65	}
