    86	            ps.setLong(1, personId);
    87	            ps.setDate(2, Date.valueOf(date));
    88	            try (ResultSet rs = ps.executeQuery()) {
    89	                if (rs.next()) grade = rs.getString(1);
    90	            }
    91	        }
    92	        if (grade != null) {
    93	            String own = setting(c, sheetId, "terms-" + grade, date);
    94	            if (own != null) return Integer.valueOf(own);
    95	        }
    96	        String terms = setting(c, sheetId, "terms", date);
    97	        return terms == null ? 14 : Integer.valueOf(terms);
    98	    }
