22	/** The sheet's figures as shown: each person's claimed, due-total and overdue-total, and the sheet's
23	 *  claimed-total, due-total and overdue-total. A change takes them before it writes, then after its own audit lines records one ROLLUP
24	 *  line per person whose figures moved (people in list order; a new person counts as
25	 *  moved), then a TOTALS line when the sheet's totals moved, then, while the sheet has an alert threshold, one ALERT
26	 *  line per person (in list order) whose due-total went from at or below it (or none) to above it. */
27	@Service
28	public class Rollup {
29	
30	    /** A person's figures: claimed (two decimals), due-total (two decimals, or 'n/a') and overdue-total
31	     *  (two decimals: the sum of the dues now of their counting claims that are overdue, skipping those with none), and
32	     *  score (the sum of the dues now of their counting SETTLED claims that correct nothing divided by 100, rounded half to even to a whole
33	     *  number, minus 5 for every counting claim of theirs that is overdue). */
34	    record Figures(String name, String claimed, String dueTotal, String overdueTotal, long score) {
35	        boolean same(Figures other) {
36	            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
37	                    && overdueTotal.equals(other.overdueTotal);
38	        }
39	    }
40	
41	    /** The figures of a sheet at one moment, people by id in list order. */
42	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
43	    }
44	
45	    private final PersonRepository people;
46	    private final ClaimRepository claims;
47	    private final SheetRepository sheets;
48	    private final SettingsRepository settings;
49	    private final PoolRepository pools;
50	    private final Audit audit;
51	
52	    public Rollup(PersonRepository people, ClaimRepository claims, SheetRepository sheets, SettingsRepository settings,
53	            PoolRepository pools, Audit audit) {
54	        this.pools = pools;
55	        this.settings = settings;
56	        this.people = people;
57	        this.claims = claims;
58	        this.sheets = sheets;
59	        this.audit = audit;
60	    }
61	
62	    /** The sheet's figures now. A person's claimed is the sum of their counting claims' amounts, leaving out corrections
63	     *  (claims that correct another). A person's due-total is the sum of their counting claims' dues now (late charges included),
64	     *  skipping those with none, less the parts of them its holders hold, plus their parts of the counting claims shared
65	     *  with them (see {@link ClaimRepository#part}: a holder whose grade has no rate holds 0.00); 'n/a' when no rate for the grade they have on the sheet's today is in force
66	     *  then and no counting claim keeps a fixed figure or has a due (at the grade it was claimed under). A due-total is at most the sheet's cap less the person's cut total (the cap in force on the date of their latest counting claim; on the sheet's today when they have none), not below 0.00 (an 'n/a' is not capped). The sheet's due-total skips 'n/a'.
67	     *  The sheet's due-total and overdue-total leave out the single highest and lowest person's figure when three or more
68	     *  people have one. */
69	    public Snapshot take(String sheetId) {
70	        List<Person> everyone = people.list(sheetId);
71	        Map<Long, Figures> figures = new LinkedHashMap<>();
72	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
73	        List<BigDecimal> dues = new ArrayList<>();
74	        List<BigDecimal> overdues = new ArrayList<>();
75	        if (!everyone.isEmpty()) {
76	            LocalDate today = sheets.today(sheetId);
77	            List<Claim> all = claims.list(sheetId);
78	            Map<Long, BigDecimal> cuts = null;
79	            Map<String, List<ClaimShare>> shares = claims.shares(sheetId);
80	            Map<Long, Person> byId = new LinkedHashMap<>();
81	            for (Person p : everyone) byId.put(p.id(), p);
82	            for (Person p : everyone) {
83	                BigDecimal claimed = BigDecimal.ZERO.setScale(2);
84	                BigDecimal due = BigDecimal.ZERO.setScale(2);
85	                BigDecimal overdue = BigDecimal.ZERO.setScale(2);
86	                BigDecimal settled = BigDecimal.ZERO.setScale(2);
87	                int overdueCount = 0;
88	                boolean fixed = false;
89	                LocalDate latest = null;
90	                for (Claim c : all) {
91	                    if (c.personId() != p.id()) continue;
92	                    String on = today == null ? null : today.toString();
93	                    if (c.corrects() == null && c.countsClaimed(p.claimedHolds(on))) claimed = claimed.add(new BigDecimal(c.amount()));
94	                    if (!c.counts(p.liveHolds(on))) continue;
95	                    LocalDate dated = LocalDate.parse(c.date());
96	                    if (latest == null || dated.isAfter(latest)) latest = dated;
97	                    fixed |= c.fixed();
98	                    BigDecimal now = claims.dueNow(sheetId, c);
99	                    if (now != null) due = due.add(now).subtract(claims.parts(sheetId, c, shares.get(String.valueOf(c.id()))));
100	                    if (now != null && claims.overdue(sheetId, c, today)) overdue = overdue.add(now);
101	                    if (now != null && "SETTLED".equals(c.status()) && c.corrects() == null) settled = settled.add(now);
102	                    if (claims.overdue(sheetId, c, today)) overdueCount++;
103	                    fixed |= now != null;
104	                }
105	                for (Claim c : all) {
106	                    List<ClaimShare> held = shares.get(String.valueOf(c.id()));
107	                    if (held == null || c.personId() == p.id()) continue;
108	                    ClaimShare mine = held.stream().filter(s -> s.personId() == p.id()).findFirst().orElse(null);
109	                    Person owner = byId.get(c.personId());
110	                    if (mine == null || owner == null) continue;
111	                    if (!c.counts(owner.liveHolds(today == null ? null : today.toString()))) continue;
112	                    BigDecimal now = claims.dueNow(sheetId, c);
113	                    if (now == null) continue;
114	                    BigDecimal part = claims.part(sheetId, c, mine);
115	                    if (part == null) continue;
116	                    due = due.add(part);
117	                    fixed = true;
118	                }
119	                boolean shown = fixed || claims.rated(sheetId, p.id(), today);
120	                BigDecimal cap = latest == null ? settings.cap(sheetId) : settings.cap(sheetId, latest);
121	                if (cap != null && cuts == null) cuts = pools.cutTotals(sheetId);
122	                due = SettingsRepository.capped(due, cap, cap == null ? null : cuts.get(p.id()));
123	                figures.put(p.id(), new Figures(p.name(), claimed.toPlainString(),
124	                        shown ? due.toPlainString() : "n/a", overdue.toPlainString(),
125	                        settled.movePointLeft(2).setScale(0, RoundingMode.HALF_EVEN).longValueExact() - 5L * overdueCount));
126	                claimedTotal = claimedTotal.add(claimed);
127	                if (shown) dues.add(due);
128	                overdues.add(overdue);
129	            }
130	        }
131	        return new Snapshot(figures, claimedTotal.toPlainString(), trimmed(dues).toPlainString(),
132	                trimmed(overdues).toPlainString());
133	    }
134	
135	    /** People's figures added up, leaving out the single highest and the single lowest when there are three or more. */
136	    static BigDecimal trimmed(List<BigDecimal> figures) {
137	        List<BigDecimal> sorted = new ArrayList<>(figures);
138	        Collections.sort(sorted);
139	        if (sorted.size() >= 3) sorted = sorted.subList(1, sorted.size() - 1);
140	        BigDecimal total = BigDecimal.ZERO.setScale(2);
141	        for (BigDecimal f : sorted) total = total.add(f);
142	        return total;
143	    }
144	
145	    /** Record one SNAPSHOT line per person (in list order) with their due-total as {@code before} had it,
146	     *  ending with for=<steward> when {@code by} made the change under that steward's delegation (null when not),
147	     *  and keep it on the person with the day being left. */
148	    public void snapshot(String sheetId, String by, Snapshot before, String delegator, LocalDate dayLeft) {
149	        for (Map.Entry<Long, Figures> e : before.people().entrySet()) {
150	            Figures f = e.getValue();
151	            people.snapshot(sheetId, e.getKey(), dayLeft, f.dueTotal());
152	            audit.record("SNAPSHOT sheet=" + sheetId + " by=" + by + " name=" + f.name() + " due-total=" + f.dueTotal()
153	                    + (delegator == null ? "" : " for=" + delegator));
154	        }
155	    }
156	
157	    /** Record one SCORE line per person (in list order) with their score as {@code before} had it. */
158	    public void scores(String sheetId, String by, Snapshot before) {
159	        for (Figures f : before.people().values()) {
160	            audit.record("SCORE sheet=" + sheetId + " by=" + by + " name=" + f.name() + " score=" + f.score());
161	        }
162	    }
163	
164	    /** Record the lines for every person (in list order) and the sheet's totals, moved or not. */
165	    public void recordAll(String sheetId, String by) {
166	        Map<Long, Figures> none = Map.of();
167	        record(sheetId, by, new Snapshot(none, "", "", ""));
168	    }
169	
170	    /** Record the lines for whatever figures moved since {@code before}. */
171	    public void record(String sheetId, String by, Snapshot before) {
172	        Snapshot after = take(sheetId);
173	        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
174	            Figures now = e.getValue();
175	            if (now.same(before.people().get(e.getKey()))) continue;
176	            audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + now.name() + " claimed="
177	                    + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
178	        }
179	        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())
180	                || !after.overdueTotal().equals(before.overdueTotal())) {
181	            audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + after.claimedTotal()
182	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
183	        }
184	        BigDecimal threshold = settings.alertThreshold(sheetId);
185	        if (threshold == null) return;
186	        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
187	            Figures now = e.getValue();
188	            Figures was = before.people().get(e.getKey());
189	            if (above(now, threshold) && !above(was, threshold)) {
190	                audit.record("ALERT sheet=" + sheetId + " by=" + by + " name=" + now.name() + " due-total=" + now.dueTotal());
191	            }
192	        }
193	    }
194	
195	    /** Whether a person's due-total is above the threshold (no figures, or an 'n/a', is not). */
196	    private static boolean above(Figures f, BigDecimal threshold) {
197	        return f != null && !"n/a".equals(f.dueTotal()) && new BigDecimal(f.dueTotal()).compareTo(threshold) > 0;
198	    }
