205	    /** Whether the rate that would apply to a claim then had ended before its date. */
206	    public boolean rateEnded(Claim claim) {
207	        LocalDate date = LocalDate.parse(claim.date());
208	        Rate rate = rateOn(claim.personId(), date, addedOf(claim));
209	        return rate != null && rate.to() != null && rate.to().isBefore(date);
210	    }
211	
212	    /** Whether a rate for the grade a person had on the day was in force on it. */
213	    public boolean rated(long personId) {
214	        Rate rate = rateOn(personId, day);
215	        return rate != null && (rate.to() == null || !rate.to().isBefore(day));
216	    }
