21	/** A signed-in user's screen showing a sheet as of a date (the X-As-Of header, yyyy-mm-dd): the sheet as it stood
22	 *  at the end of that day. Every change kept in row_change (see {@link RowCapture}) made while the sheet's today
23	 *  was on or before the date counts, in the order made, every later one does not (the sheet itself always
24	 *  exists); the date stands in for the sheet's today. A read replays those changes into the asof schema's tables,
25	 *  runs the usual read against them, and removes them again, all in one transaction, so no other read sees them.
26	 *  The sheets it falls back to (its parent as it stood then, that one's parent and so on, and
27	 *  the sheets it was cloned from) are not shown as of the
28	 *  date: their rows are read as they are now, so a rate it inherits applies as it does live.
29	 *  While the date is set, every change is refused.
30	 *
31	 *  A screen may instead preview the sheet at a date (the X-Preview header, yyyy-mm-dd): its rows as they are now,
32	 *  copied into the asof schema the same way, with the date standing in for its today, so every figure that
33	 *  depends on today is worked out as of that date. Only reads look at it: every change still uses the sheet's
34	 *  real today, and nothing a change of today does happens. */
35	@Component
36	public class AsOfView {
37	
38	    public static final String HEADER = "X-As-Of";
39	    public static final String PREVIEW_HEADER = "X-Preview";
40	
41	    private final JdbcTemplate jdbc;
42	    private final RowCaptureInstaller installer;
43	    private final TransactionTemplate transaction;
44	
45	    public AsOfView(JdbcTemplate jdbc, RowCaptureInstaller installer, PlatformTransactionManager transactions) {
46	        this.jdbc = jdbc;
47	        this.installer = installer;
48	        this.transaction = new TransactionTemplate(transactions);
49	    }
50	
51	    /** The as-of date the request's screen shows; null when it shows the sheet as it is now. */
52	    public static LocalDate of(ServerHttpConnection connection) throws BadRequestException {
53	        return date(connection, HEADER, "as-of");
54	    }
55	
56	    /** The date the request's screen previews the sheet at; null when it shows the sheet at its real today. */
57	    public static LocalDate previewOf(ServerHttpConnection connection) throws BadRequestException {
58	        return date(connection, PREVIEW_HEADER, "preview");
59	    }
60	
61	    private static LocalDate date(ServerHttpConnection connection, String name, String what) throws BadRequestException {
62	        String raw = "";
63	        for (HttpHeader header : connection.getRequest().getHeaders()) {
64	            if (name.equalsIgnoreCase(header.getName())) {
65	                raw = header.getValue() == null ? "" : header.getValue().trim();
66	                break;
67	            }
68	        }
69	        if (raw.isEmpty()) return null;
70	        try {
71	            return LocalDate.parse(raw);
72	        } catch (DateTimeParseException e) {
73	            throw new BadRequestException(what + " date must be yyyy-mm-dd");
74	        }
75	    }
76	
77	    /** Refuse any change made from a screen showing the sheet as of a date (400, nothing written). */
78	    public static void refuse(ServerHttpConnection connection) throws BadRequestException {
79	        if (of(connection) != null) {
80	            throw new BadRequestException("the sheet is shown as of a date: nothing can be changed");
81	        }
82	    }
83	
84	    /** The read, as the request's screen shows the sheet: as of its date when one is set, else previewed at its
85	     *  preview date when one is set, else as it is now. */
86	    public <T> T read(ServerHttpConnection connection, String sheetId, Supplier<T> read) throws BadRequestException {
87	        LocalDate day = of(connection);
88	        if (day != null) return readAt(sheetId, day, read);
89	        LocalDate preview = previewOf(connection);
90	        if (preview != null) return readPreview(sheetId, preview, read);
91	        return read.get();
92	    }
93	
94	    /** The read run against the sheet as it stood at the end of a day, the day standing in for its today. */
95	    public <T> T readAt(String sheetId, LocalDate day, Supplier<T> read) {
96	        return readIn(sheetId, day, true, read);
97	    }
98	
99	    /** The read run against the sheet as it is now, a day standing in for its today. */
100	    public <T> T readPreview(String sheetId, LocalDate day, Supplier<T> read) {
101	        return readIn(sheetId, day, false, read);
102	    }
103	
104	    private <T> T readIn(String sheetId, LocalDate day, boolean asOf, Supplier<T> read) {
105	        return transaction.execute(status -> {
106	            Map<String, List<Object[]>> rows = asOf ? replay(sheetId, day) : new LinkedHashMap<>();
107	            if (!asOf) copy(sheetId);
108	            for (Map.Entry<String, List<Object[]>> e : rows.entrySet()) {
109	                RowCaptureInstaller.Table table = installer.tables().get(e.getKey());
110	                String marks = String.join(", ", table.columns().stream().map(c -> "?").toList());
111	                for (Object[] row : e.getValue()) {
112	                    jdbc.update("INSERT INTO ASOF.\"" + table.name() + "\" VALUES (" + marks + ")", row);
113	                }
114	            }
115	            if (asOf && rows.getOrDefault("SHEET", List.of()).isEmpty()) {
116	                jdbc.update("INSERT INTO ASOF.SHEET SELECT * FROM PUBLIC.SHEET WHERE id = ?", sheetId);
117	            }
118	            jdbc.update("UPDATE ASOF.SHEET SET today = ? WHERE id = ?", Date.valueOf(day), sheetId);
119	            List<String> shown = new ArrayList<>(List.of(sheetId));
120	            for (String at = parent("ASOF", sheetId); at != null && !shown.contains(at); at = parent("PUBLIC", at)) {
121	                shown.add(at);
122	                copy(at);
123	            }
124	            for (String at : fallbacks(sheetId)) {
125	                if (shown.contains(at)) continue;
126	                shown.add(at);
127	                copy(at);
128	            }
129	            jdbc.execute("SET SCHEMA ASOF");
130	            try {
131	                return read.get();
132	            } finally {
133	                jdbc.execute("SET SCHEMA PUBLIC");
134	                for (String at : shown) {
135	                    for (RowCaptureInstaller.Table table : installer.tables().values()) {
136	                        jdbc.update("DELETE FROM ASOF.\"" + table.name() + "\" WHERE \""
137	                                + table.columns().get(table.sheetColumn()) + "\" = ?", at);
138	                    }
139	                }
140	            }
141	        });
142	    }
143	
144	    /** Copy a sheet's rows as they are now into the asof schema. */
145	    private void copy(String sheetId) {
146	        for (RowCaptureInstaller.Table table : installer.tables().values()) {
147	            jdbc.update("INSERT INTO ASOF.\"" + table.name() + "\" SELECT * FROM PUBLIC.\"" + table.name()
148	                    + "\" WHERE \"" + table.columns().get(table.sheetColumn()) + "\" = ?", sheetId);
149	        }
150	    }
151	
152	    /** Every sheet a sheet may fall back to: its parent and the sheet it was cloned from as they stood then, then
153	     *  theirs as they are now, and so on. */
154	    private List<String> fallbacks(String sheetId) {
155	        List<String> found = new ArrayList<>();
156	        java.util.Deque<String> pending = new java.util.ArrayDeque<>(List.of(sheetId));
157	        while (!pending.isEmpty()) {
158	            String at = pending.poll();
159	            String schema = at.equals(sheetId) ? "ASOF" : "PUBLIC";
160	            for (Map<String, Object> row : jdbc.queryForList("SELECT parent_id, cloned_from FROM " + schema + ".SHEET WHERE id = ?",
161	                    at)) {
162	                for (Object next : row.values()) {
163	                    if (next != null && !next.equals(sheetId) && !found.contains(next)) {
164	                        found.add((String) next);
165	                        pending.add((String) next);
166	                    }
167	                }
168	            }
169	        }
170	        return found;
171	    }
172	
173	    /** A sheet's parent in a schema; null when it has none (or is not there). */
174	    private String parent(String schema, String sheetId) {
175	        List<String> found = jdbc.queryForList("SELECT parent_id FROM " + schema + ".SHEET WHERE id = ?", String.class, sheetId);
176	        return found.isEmpty() ? null : found.get(0);
177	    }
178	
179	    /** The sheet's rows as of the end of a day, by table: the kept changes made while its today was on or before
180	     *  it, applied in the order made. An insert adds its row (the sheet's own always counts); an update changes
181	     *  the columns it changed of the row it changed (found by its primary key, else by all its values), and a
182	     *  delete removes that row; one whose row is not there (it was added later) changes nothing. */
183	    private Map<String, List<Object[]>> replay(String sheetId, LocalDate day) {
184	        Map<String, List<Object[]>> rows = new LinkedHashMap<>();
185	        Date on = Date.valueOf(day);
186	        jdbc.query("SELECT on_date, table_name, old_row, new_row FROM ROW_CHANGE WHERE sheet_id = ? ORDER BY id", rs -> {
187	            RowCaptureInstaller.Table table = installer.tables().get(rs.getString("table_name"));
188	            if (table == null) return;
189	            Object[] before = RowCapture.read(rs.getBytes("old_row"));
190	            Object[] after = RowCapture.read(rs.getBytes("new_row"));
191	            boolean counts = !rs.getDate("on_date").after(on) || (before == null && table.name().equals("SHEET"));
192	            if (!counts) return;
193	            List<Object[]> kept = rows.computeIfAbsent(table.name(), k -> new ArrayList<>());
194	            if (before == null) {
195	                if (!table.key().isEmpty()) {
196	                    int same = find(kept, table, after);
197	                    if (same >= 0) kept.remove(same);
198	                }
199	                kept.add(after.clone());
200	                return;
201	            }
202	            int found = find(kept, table, before);
203	            if (found < 0) return;
204	            if (after == null) {
205	                kept.remove(found);
206	                return;
207	            }
208	            Object[] row = kept.get(found);
209	            for (int i = 0; i < row.length && i < after.length; i++) {
210	                if (!Objects.deepEquals(before[i], after[i])) row[i] = after[i];
211	            }
212	        }, sheetId);
213	        return rows;
214	    }
215	
216	    /** The position of the kept row a change's row is: the one with its primary key, else with all its values. */
217	    private static int find(List<Object[]> kept, RowCaptureInstaller.Table table, Object[] row) {
218	        for (int i = kept.size() - 1; i >= 0; i--) {
219	            Object[] k = kept.get(i);
220	            boolean same = true;
221	            if (table.key().isEmpty()) {
222	                same = Arrays.deepEquals(k, row);
223	            } else {
224	                for (int c : table.key()) same &= Objects.deepEquals(k[c], row[c]);
225	            }
226	            if (same) return i;
227	        }
228	        return -1;
229	    }
230	}
