79	    /** Keep a person's retirement from a date. */
80	    public void retire(String sheetId, long personId, LocalDate from) {
81	        jdbc.update("INSERT INTO retire_history (sheet_id, on_date, person_id, retired_from) VALUES (?, " + TODAY
82	                + ", ?, ?)", sheetId, sheetId, personId, date(from));
