96	    /** The sheet as it stood at the end of a day: the changes made while its today was on or before that day,
97	     *  each kept value the last of them (in the order made). */
98	    public SheetAsOf asOf(String sheetId, LocalDate day) {
99	        Date on = Date.valueOf(day);
100	        Map<Long, Claim> claims = new LinkedHashMap<>();
101	        jdbc.query("SELECT h.* FROM claim_history h WHERE h.sheet_id = ? AND h.id = (SELECT MAX(l.id) FROM claim_history l"
102	                + " WHERE l.sheet_id = h.sheet_id AND l.claim_id = h.claim_id AND l.on_date <= ?) ORDER BY h.claim_id",
103	                (RowCallbackHandler) rs -> {
104	                    String status = rs.getString("status");
105	                    LocalDate deferredUntil = local(rs.getDate("deferred_until"));
106	                    BigDecimal settled = rs.getBigDecimal("settled_due");
107	                    BigDecimal stated = rs.getBigDecimal("stated_due");
108	                    claims.put(rs.getLong("claim_id"), new Claim(rs.getLong("claim_id"), rs.getLong("person_id"),
109	                            rs.getBigDecimal("amount").setScale(2).toPlainString(), local(rs.getDate("claim_date")).toString(),
110	                            "", status, null, settled == null ? null : settled.setScale(2).toPlainString(), null,
111	                            rs.getBoolean("stated"), stated == null ? null : stated.setScale(2).toPlainString(),
112	                            rs.getString("corrects"), local(rs.getDate("due_by")).toString(), rs.getBoolean("stated_na"),
113	                            deferredUntil == null ? null : deferredUntil.toString(),
114	                            (status.equals("OPEN") || status.equals("SETTLED")) && !rs.getBoolean("stated") && deferredUntil != null && deferredUntil.isAfter(day), 0, null, false, null, null, null, null,
115	                            rs.getBoolean("waived"), 0, rs.getBoolean("held")));
116	                }, sheetId, on);
117	        Map<Long, TreeMap<LocalDate, String>> grades = new HashMap<>();
118	        jdbc.query("SELECT person_id, grade, from_date FROM grade_history WHERE sheet_id = ? AND on_date <= ? ORDER BY id",
119	                (RowCallbackHandler) rs -> grades.computeIfAbsent(rs.getLong("person_id"), k -> new TreeMap<>())
120	                        .put(from(rs.getDate("from_date")), rs.getString("grade")), sheetId, on);
121	        Map<String, TreeMap<LocalDate, List<SheetAsOf.Rate>>> rates = new HashMap<>();
122	        jdbc.query("SELECT grade, pct, from_date, to_date, after_seq, withdrawn FROM rate_history WHERE sheet_id = ? AND on_date <= ?"
123	                + " ORDER BY id", (RowCallbackHandler) rs -> {
124	                    TreeMap<LocalDate, List<SheetAsOf.Rate>> dated = rates.computeIfAbsent(rs.getString("grade"), k -> new TreeMap<>());
125	                    LocalDate from = from(rs.getDate("from_date"));
126	                    if (rs.getBoolean("withdrawn")) {
127	                        // A withdrawal takes back the last rate set from that date.
128	                        List<SheetAsOf.Rate> sets = dated.get(from);
129	                        if (sets != null && !sets.isEmpty()) sets.remove(sets.size() - 1);
130	                        if (sets != null && sets.isEmpty()) dated.remove(from);
131	                        return;
132	                    }
133	                    dated.computeIfAbsent(from, k -> new ArrayList<>()).add(new SheetAsOf.Rate(rs.getBigDecimal("pct"),
134	                            local(rs.getDate("to_date")), rs.getObject("after_seq", Long.class)));
135	                }, sheetId, on);
136	        Map<Long, Long> added = new HashMap<>();
137	        jdbc.query("SELECT id, added_seq FROM claim WHERE sheet_id = ?",
138	                (RowCallbackHandler) rs -> added.put(rs.getLong("id"), rs.getLong("added_seq")), sheetId);
139	        Map<String, TreeMap<LocalDate, String>> settings = new HashMap<>();
140	        jdbc.query("SELECT setting_key, from_date, setting FROM setting_history WHERE sheet_id = ? AND on_date <= ? ORDER BY id",
141	                (RowCallbackHandler) rs -> settings.computeIfAbsent(rs.getString("setting_key"), k -> new TreeMap<>())
142	                        .put(from(rs.getDate("from_date")), rs.getString("setting")), sheetId, on);
143	        List<Date> policy = jdbc.query("SELECT policy_date FROM policy_history WHERE sheet_id = ? AND on_date <= ?"
144	                + " ORDER BY id DESC LIMIT 1", (rs, i) -> rs.getDate("policy_date"), sheetId, on);
145	        Map<Long, List<Hold>> holds = new HashMap<>();
146	        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? AND held_on <= ? ORDER BY id",
147	                (RowCallbackHandler) rs -> holds.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>())
148	                        .add(new Hold(text(rs.getDate("from_date")), text(rs.getDate("to_date")))), sheetId, on);
149	        Map<Long, String> retired = new HashMap<>();
150	        jdbc.query("SELECT person_id, retired_from FROM retire_history WHERE sheet_id = ? AND on_date <= ? ORDER BY id",
151	                (RowCallbackHandler) rs -> retired.put(rs.getLong("person_id"), text(rs.getDate("retired_from"))), sheetId, on);
152	        return new SheetAsOf(day, claims, grades, rates, settings, policy.isEmpty() ? null : local(policy.get(0)), holds,
153	                retired, c -> {
154	                    List<Date> found = jdbc.queryForList("SELECT claim_date FROM claim WHERE sheet_id = ? AND person_id = ?"
155	                            + " AND claim_no = ? ORDER BY id LIMIT 1", Date.class, sheetId, c.personId(), c.corrects());
156	                    return found.isEmpty() ? null : found.get(0).toLocalDate().toString();
157	                }, added);
158	    }
159	
160	    private static LocalDate local(Date d) {
161	        return d == null ? null : d.toLocalDate();
162	    }
163	
164	    private static String text(Date d) {
165	        return d == null ? null : d.toLocalDate().toString();
166	    }
167	
168	    /** A from-date as a key: a null one is the beginning of time. */
169	    private static LocalDate from(Date d) {
170	        return d == null ? SheetAsOf.BEGINNING : d.toLocalDate();
171	    }
172	}
