 11	/** The signed-in user's locale ('en' until they choose, and while it is being read). */
 12	export function useLocale(): string {
 13	  const [user] = useSignedInUser();
 14	  const locale = useQuery({
 15	    queryKey: localeKey(user),
 16	    queryFn: () => getJsonNow<UserLocale>('/api/locale'),
