 22	/** A figure: the whole text a number with two decimals. */
 23	const FIGURE = /^(-?)(\d+)\.(\d{2})$/;
 24	
 25	/** A shown value as this locale shows it: under 'de' a figure reads 1.234,56 (a dot every three digits, a comma
 26	 *  before the decimals); anything else, and every value under 'en', is shown as it is. Only what the screen shows
 27	 *  goes through this: entries are typed with a dot, and exports and audit lines keep the dot. */
 28	export function figureIn(locale: string, value: string): string {
 29	  const m = locale === 'de' ? FIGURE.exec(value.trim()) : null;
 30	  if (!m) return value;
 31	  return `${m[1]}${m[2].replace(/\B(?=(\d{3})+$)/g, '.')},${m[3]}`;
 32	}
