381	 *  split by the claim's age (0 to 30 days, 31 to 60, 61 or more), skipping those with none.
382	 *  Empty until the sheet's today is loaded. */
383	export function useAging(sheetId: string): Map<number, Aging> {
384	  const people = usePeople(sheetId);
385	  const claims = useClaims(sheetId);
386	  const rates = useRates(sheetId);
387	  const settings = useSettings(sheetId).data;
388	  const today = useSheetToday(sheetId).data?.today;
389	  const holds = holdsById(people.data, today);
390	  const aging = new Map<number, Aging>();
391	  if (today === undefined) return aging;
392	  for (const p of people.data ?? []) {
393	    const buckets: [string[], string[], string[]] = [[], [], []];
394	    for (const c of claims.data ?? []) {
395	      if (c.personId !== p.id || !isOpen(c) || !counts(c, holds, today)) continue;
396	      const age = ageDays(c.date, today);
397	      const d = claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(p, c.date), c.date, c.added), settings, today, gradeOn(p, c.date));
398	      buckets[age <= 30 ? 0 : age <= 60 ? 1 : 2].push(d);
399	    }
400	    aging.set(p.id, { d0to30: sumDues(buckets[0]), d31to60: sumDues(buckets[1]), d61: sumDues(buckets[2]) });
401	  }
402	  return aging;
403	}
