399	/** A person's statements: how many have been taken, the last one's due-total and date (blank before
400	 *  the first), and a button that takes one. Taking a statement records their due-total and binds each
401	 *  of their counting claims to the figure it has then (unbinding the rest), until the next one; a
402	 *  steward can cancel the last one, its claims going live again. A date beside the button takes the
403	 *  statement as of that date (on or before the sheet's today; blank: now); it is cleared once that statement is
404	 *  taken or refused. Below, one line per statement still standing (in the order taken, oldest first), as its date and
405	 *  due-total. A last button downloads the statement as a CSV file: a header line, then one line per claim of
406	 *  theirs its last statement binds, oldest first, with the figure it was bound to ('n/a' when bound to n/a; the
407	 *  claim's fixed due when bound with no figure). */
408	function PersonStatement({ sheetId, personId }: { sheetId: string; personId: number }) {
409	  const fig = useFigure();
410	  const people = usePeople(sheetId);
411	  const queryClient = useQueryClient();
412	  const claims = useClaims(sheetId);
413	  const p = people.data?.find((x) => x.id === personId);
414	  const [asof, setAsof] = useState('');
415	
416	  const take = useMutation({
417	    mutationFn: (date: string) =>
418	      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/statement`, { asof: date }),
419	    // The date is for the one statement it was typed for: taken or refused, the next one is now unless a
420	    // date is typed again.
421	    onSettled: () => setAsof(''),
422	    onSuccess: async () => {
423	      await Promise.all([
424	        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
425	        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
426	      ]);
427	    },
428	  });
429	  const unstate = useMutation({
430	    mutationFn: () =>
431	      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/unstate`, {}),
432	    onSuccess: async () => {
433	      await Promise.all([
434	        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
435	        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
436	      ]);
437	    },
438	  });
439	  const { reset: resetTake } = take;
440	  const { reset: resetUnstate } = unstate;
441	  const reset = useCallback(() => {
442	    resetTake();
443	    resetUnstate();
444	  }, [resetTake, resetUnstate]);
445	  const announce = usePersonRowAction(sheetId, personId, reset);
446	  const error = take.error ?? unstate.error;
447	
448	  // Re-read the claims first: another user may have stated, settled or changed them since they were loaded.
449	  const exportStatement = async () => {
450	    const mine = ((await fresh(claims)) ?? []).filter((c) => c.personId === personId && c.stated).reverse();
451	    const lines = [['number', 'date', 'amount', 'figure', 'status']];
452	    for (const c of mine) {
453	      lines.push([c.number ?? '', c.date, c.amount, c.statedNa ? 'n/a' : c.statedDue ?? c.due ?? '', c.status]);
454	    }
455	    downloadCsv(lines, `statement-${sheetId}-${personId}.csv`);
456	  };
457	
458	  return (
459	    <>
460	      <Col id="statement-count"><td data-testid="person-statement-count">{p?.statementCount ?? 0}</td></Col>
461	      <Col id="stated-total"><td data-testid="person-stated-total">{fig(p?.statedTotal ?? '')}</td></Col>
462	      <Col id="statement-date"><td data-testid="person-statement-date">{p?.statementDate ?? ''}</td></Col>
463	      <td>
464	        {(p?.statements ?? []).map((s, i) => (
465	          <div key={i} data-testid="person-statement-line-line">
466	            {s.date} {fig(s.dueTotal)}
467	          </div>
468	        ))}
469	      </td>
470	      <td>
471	        <input
472	          type="text"
473	          placeholder="yyyy-mm-dd"
474	          data-testid="person-statement-asof"
475	          aria-label="Statement as of"
476	          value={asof}
477	          onChange={(e) => {
478	            setAsof(e.target.value);
479	            reset();
480	          }}
481	        />
482	        <button
483	          type="button"
484	          data-testid="person-statement"
485	          disabled={take.isPending}
486	          onClick={() => {
487	            announce();
488	            reset();
489	            take.mutate(asof);
490	          }}
491	        >
492	          Statement
493	        </button>
494	        <button
495	          type="button"
496	          data-testid="person-unstate"
497	          disabled={unstate.isPending}
498	          onClick={() => {
499	            announce();
500	            reset();
501	            unstate.mutate();
502	          }}
503	        >
504	          Cancel statement
505	        </button>
506	        <button type="button" data-testid="person-export-statement" onClick={() => void exportStatement()}>
507	          Export statement (CSV)
508	        </button>
509	        {error && <span data-testid="person-error">{error.message}</span>}
510	      </td>
511	    </>
512	  );
513	}
