683	    /** The terms-th business day after a date, skipping every Saturday, Sunday and one of the holidays (yyyy-MM-dd). */
684	    public static LocalDate businessDaysAfter(java.util.Set<String> holidays, LocalDate date, int terms) {
685	        int counted = 0;
686	        while (counted < terms) {
687	            date = date.plusDays(1);
688	            java.time.DayOfWeek day = date.getDayOfWeek();
689	            if (day != java.time.DayOfWeek.SATURDAY && day != java.time.DayOfWeek.SUNDAY
690	                    && !holidays.contains(date.toString())) {
691	                counted++;
692	            }
693	        }
694	        return date;
695	    }
