 57	/** Works out one sheet's figures with the same hooks its header uses, and hands them up; shows nothing. */
 58	function SheetFigures({ sheetId, grades: shownGrades, onFigures }: { sheetId: string; grades: readonly string[]; onFigures: (id: string, f: Figures) => void }) {
 59	  const people = usePeopleNames(sheetId).data ?? '';
 60	  const due = [...useDueTotals(sheetId).values()].join(',');
 61	  const overdue = [...useOverdue(sheetId).values()].map((f) => f.total).join(',');
 62	  const settledOpen = [...useSettledOpenTotals(sheetId).values()];
 63	  const settled = settledOpen.map((s) => s.settled).join(',');
 64	  const open = settledOpen.map((s) => s.open).join(',');
 65	  const cut = [...useCutTotals(sheetId).values()].join(',');
 66	  const dueTotals = useDueTotals(sheetId);
 67	  const current = (usePeople(sheetId).data ?? []).filter((p) => !p.retiredFrom);
 68	  const claims = useClaims(sheetId).data;
 69	  // Joined into strings so the effect below only fires when a figure changes.
 70	  const grades = shownGrades.map((g) =>
 71	    sumDues(current.filter((p) => p.grade === g).map((p) => dueTotals.get(p.id) ?? 'n/a'))).join(',');
 72	  const statuses = STATUSES.map((s) => countWithStatus(claims, s)).join(',');
 73	  useEffect(
 74	    () => onFigures(sheetId, { people, due, overdue, settled, open, cut, grades, statuses }),
 75	    [sheetId, people, due, overdue, settled, open, cut, grades, statuses, onFigures],
 76	  );
 77	  return null;
 78	}
