 80	/** The consolidated figures over the sheet and all its descendants: the number of people (each counted once over
 81	 *  the tree: people whose names or aliases match are one person), the due-total, overdue-total, settled-total,
 82	 *  open-total and cut total of every person
 83	 *  of the tree added up, leaving out the single highest and the single lowest figure over the whole tree when three
 84	 *  or more people have one, per grade the due-totals of the people on
 85	 *  it added up, and per status the count of claims, all as of the screen's as-of date when one is
 86	 *  set. A sheet with no children shows its own. */
 87	function Consolidated({ sheetId }: { sheetId: string }) {
 88	  const fig = useFigure();
 89	  const grades = useGrades(sheetId);
 90	  const descendants = useDescendants(sheetId);
 91	  const [figures, setFigures] = useState<Record<string, Figures>>({});
 92	  const [onFigures] = useState(() => (id: string, f: Figures) => setFigures((all) => ({ ...all, [id]: f })));
 93	  const sheets = [sheetId, ...(descendants.data ?? [])];
 94	  const shown = sheets.map((id) => figures[id]).filter((f): f is Figures => f !== undefined);
 95	  const sum = (pick: (f: Figures) => string) => money(shown.reduce((s, f) => s + hundredths(pick(f)), 0n));
 96	  const trimmed = (pick: (f: Figures) => string) =>
 97	    trimmedSum(shown.flatMap((f) => (pick(f) === '' ? [] : pick(f).split(','))));
 98	  const gradeDue = (i: number) => sum((f) => f.grades.split(',')[i] ?? '0.00');
 99	  const statusCount = (i: number) => shown.reduce((n, f) => n + Number(f.statuses.split(',')[i]), 0);
100	  return (
101	    <p data-testid="consolidated">
102	      {sheets.map((id) => (
103	        <SheetFigures key={id} sheetId={id} grades={grades} onFigures={onFigures} />
104	      ))}
105	      Consolidated: people <strong data-testid="consolidated-people-count">{countPeople(shown.map((f) => f.people))}</strong>
106	      {' '}· due total <strong data-testid="consolidated-due-total">{fig(trimmed((f) => f.due))}</strong>
107	      {' '}· overdue total <strong data-testid="consolidated-overdue-total">{fig(trimmed((f) => f.overdue))}</strong>
108	      {' '}· settled total <strong data-testid="consolidated-settled-total">{fig(trimmed((f) => f.settled))}</strong>
109	      {' '}· open total <strong data-testid="consolidated-open-total">{fig(trimmed((f) => f.open))}</strong>
110	      {' '}· cut total <strong data-testid="consolidated-cut-total">{fig(trimmed((f) => f.cut))}</strong>
111	      {grades.map((g, i) => (
112	        <span key={g}>
113	          {' '}· grade {g} due total <strong data-testid={`consolidated-grade-${g}-due-total`}>{fig(gradeDue(i))}</strong>
114	        </span>
115	      ))}
116	      {STATUSES.map((s, i) => (
117	        <span key={s}>
118	          {' '}· {s} <strong data-testid={`consolidated-status-${s}-count`}>{statusCount(i)}</strong>
119	        </span>
120	      ))}
121	    </p>
122	  );
123	}
