287	/** The order of a timeline's kinds on one date. */
288	const KINDS = ['grade', 'claim', 'hold', 'retired', 'unretired'] as const;
289	
290	type Entry = { date: string; kind: (typeof KINDS)[number]; text: string };
291	
292	/** A person's timeline: a line per dated thing about them, by date, and on one date their grade changes, then
293	 *  claims, then holds, then retirements, then unretirements (alike lines in text order). A grade they were first
294	 *  given and a hold with no from-date carry no date and are left out. */
295	export function timeline(person: Person, claims: readonly Claim[]): string[] {
296	  const entries: Entry[] = [];
297	  for (const g of person.grades ?? []) {
298	    if (g.from !== null) entries.push({ date: g.from, kind: 'grade', text: `${g.from} grade ${g.grade}` });
299	  }
300	  for (const c of claims) {
301	    if (c.personId === person.id) entries.push({ date: c.date, kind: 'claim', text: `${c.date} claim ${c.amount} ${c.status}` });
