246	/** A plan's first five dates after today and on or before its end, in order: the start then every N days, or
247	 *  (monthly) that day in every month from the start's month, falling on the month's last day when beyond it,
248	 *  those before the start and those in one of its pauses left out — the same dates the generate makes. */
249	export function nextPlanDates(plan: Plan, today: string): string[] {
250	  const out: string[] = [];
251	  const start = Date.parse(`${plan.start}T00:00:00Z`);
252	  const end = Date.parse(`${plan.end}T00:00:00Z`);
253	  const after = Date.parse(`${today}T00:00:00Z`);
254	  if (Number.isNaN(start) || Number.isNaN(end) || Number.isNaN(after)) return out;
255	  if (plan.day == null) {
256	    const step = (plan.every ?? 0) * DAY_MS;
257	    if (step <= 0) return out;
258	    let on = start;
259	    if (on <= after) on += Math.floor((after - on) / step + 1) * step;
260	    for (; on <= end && out.length < 5; on += step) if (!skipped(plan, isoDay(on))) out.push(isoDay(on));
261	    return out;
262	  }
263	  const first = new Date(start);
264	  for (let m = first.getUTCFullYear() * 12 + first.getUTCMonth(); out.length < 5; m++) {
265	    const y = Math.floor(m / 12);
266	    const mo = m % 12;
267	    if (Date.UTC(y, mo, 1) > end) break;
268	    const last = new Date(Date.UTC(y, mo + 1, 0)).getUTCDate();
269	    const on = Date.UTC(y, mo, Math.min(plan.day, last));
270	    if (on >= start && on > after && on <= end && !skipped(plan, isoDay(on))) out.push(isoDay(on));
271	  }
272	  return out;
273	}
