175	/** A button that downloads the policy versions as a CSV file: a header line, then one line per version, oldest
176	 *  first, with its from-date (blank when it has none), the setting it changed and its value (blank when blank), how
177	 *  many claims have it as their policy version, and the due now of those of them that count, added up. */
178	function ExportPolicy({ sheetId }: { sheetId: string }) {
179	  const people = usePeople(sheetId);
180	  const claims = useClaims(sheetId);
181	  const rates = useRates(sheetId);
182	  const settingsQ = useSettings(sheetId);
183	  const todayQ = useSheetToday(sheetId);
184	
185	  // Re-read everything first: another user may have changed the claims or settings since they were loaded.
186	  const download = async () => {
187	    const [ps, cs, rs, settings, td] = await Promise.all(
188	      [fresh(people), fresh(claims), fresh(rates), fresh(settingsQ), fresh(todayQ)]);
189	    const today = td?.today;
190	    const holds = holdsById(ps, today);
191	    const byId = new Map((ps ?? []).map((p) => [p.id, p]));
192	    const count = new Map<number, number>();
193	    const dues = new Map<number, string[]>();
194	    if (settings !== undefined) {
195	      for (const c of cs ?? []) {
196	        const v = policyVersionOn(settings, c.date);
197	        count.set(v, (count.get(v) ?? 0) + 1);
198	        const owner = byId.get(c.personId);
199	        if (owner === undefined || !counts(c, holds, today)) continue;
200	        const grade = gradeOn(owner, c.date);
201	        dues.set(v, [...(dues.get(v) ?? []), claimDueNow(c, cs, rateFor(rs, grade, c.date, c.added), settings, today, grade)]);
202	      }
203	    }
204	    const lines = [['version', 'from', 'key', 'value', 'claims', 'due-total']];
205	    for (const p of settings?.policyVersionDetails ?? []) {
206	      lines.push([String(p.version), p.from ?? '', p.key, p.value ?? '', String(count.get(p.version) ?? 0), sumDues(dues.get(p.version) ?? [])]);
207	    }
208	    downloadCsv(lines, `policy-${sheetId}.csv`);
209	  };
210	
211	  return (
212	    <button type="button" data-testid="export-policy" onClick={() => void download()}>
213	      Export policy versions (CSV)
214	    </button>
215	  );
216	}
