221	/** Works out one sheet's lines (sheet id, name, grade, due-total as shown, 'n/a' when none; in list order, retired
222	 *  people included) with the same hooks its own screen uses, and hands them up once all is read; shows nothing. */
223	function SheetPeopleLines({ sheetId, onLines }: { sheetId: string; onLines: (id: string, lines: string[][]) => void }) {
224	  const people = usePeople(sheetId);
225	  const ready = [people, useClaims(sheetId), useRates(sheetId), useSheetToday(sheetId), useSettings(sheetId), usePools(sheetId)]
226	    .every((q) => q.isSuccess);
227	  const due = useDueTotals(sheetId);
228	  const lines = (people.data ?? []).map((p) => [sheetId, p.name, p.grade, due.get(p.id) ?? 'n/a']);
229	  // Joined into a string so the effect below only fires when a line changes.
230	  const joined = JSON.stringify(lines);
231	  useEffect(() => {
232	    if (ready) onLines(sheetId, JSON.parse(joined) as string[][]);
233	  }, [ready, sheetId, joined, onLines]);
234	  return null;
235	}
