237	/** A button that downloads the people of the whole tree as a CSV file: a header line, then one line per person,
238	 *  this sheet's people first in list order, then the other sheets' of its tree by sheet id. The other sheets are
239	 *  re-read from the store on each press. */
240	function ExportTree({ sheetId }: { sheetId: string }) {
241	  const queryClient = useQueryClient();
242	  const [run, setRun] = useState<TreeRun | null>(null);
243	  const [found, setFound] = useState<{ n: number; lines: Record<string, string[][]> }>({ n: 0, lines: {} });
244	  const [counter, setCounter] = useState(0);
245	  const [onLines] = useState(() => (id: string, lines: string[][]) =>
246	    setFound((f) => ({ ...f, lines: { ...f.lines, [id]: lines } })));
247	
248	  const start = async () => {
249	    const n = counter + 1;
250	    setCounter(n);
251	    setRun(null);
252	    setFound({ n, lines: {} });
253	    const { sheets } = await getJson<{ sheets: string[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/tree`);
254	    for (const id of sheets) queryClient.removeQueries({ queryKey: ['sheet', id] });
255	    setRun({ n, sheets: [sheetId, ...sheets] });
256	  };
257	
258	  const done = run !== null && found.n === run.n && run.sheets.every((id) => found.lines[id] !== undefined);
259	  useEffect(() => {
260	    if (!done || run === null) return;
261	    downloadCsv([['sheet', 'name', 'grade', 'due-total'], ...run.sheets.flatMap((id) => found.lines[id])], `tree-${sheetId}.csv`);
262	    setRun(null);
263	  }, [done, run, found, sheetId]);
264	
265	  return (
266	    <>
267	      <button type="button" data-testid="export-tree" onClick={() => void start()}>
268	        Export tree (CSV)
269	      </button>
270	      {run?.sheets.map((id) => (
271	        <SheetPeopleLines key={`${run.n}-${id}`} sheetId={id} onLines={onLines} />
272	      ))}
273	    </>
274	  );
275	}
